$script:SplashTopmostTickLastExMsg = $null
# 2214l / 2214m: OOBE GA_ROOT (wwahost) -> last Utc when SetWindowPos(..., below splash) pass=1 was attempted (throttle 4s per root).
$script:Oobe2214lZBehindSplashLastUtcByRoot = New-Object 'System.Collections.Generic.Dictionary[string,System.DateTimeOffset]'
# 2214m: pass=1 Z-stomp ran this SplashTopmostRefresh tick -> allow pass=2 after 2214b reclaim (same throttle bucket).
$script:Oobe2214mDid2214lPass1ZStompThisTick = $false
