$script:Fb2241SkipWwahostMinForThisTick = $false

# 2213d: self-logging - no code path can leave this script without
# writing at least 2 log lines (STARTUP + EXIT or STARTUP + TRAP).
# Field evidence on F:\fb-dump-final-1430 proved Defender was killing
# the splash powershell silently; the launcher reported exit 0 because
# $ErrorActionPreference='Continue' swallowed every dispatcher throw.
# Write-SplashLog appends ONE line per call to splash-ui.log with PID,
# session ID, and timestamp, so the last successful checkpoint pinpoints
# where the process died. The trap catches any uncaught terminating
# error (including [Environment]::Exit from a hostile process) and
# logs the type + stack trace before continuing.
$script:SplashLogPath = 'C:\Windows\Setup\FirstBase\Logs\splash-ui.log'

function Write-SplashLog {
    param([string]$Msg, [string]$Level = 'INFO')
    try {
        $session = 'unknown'
        try { $session = (Get-Process -Id $PID -ErrorAction SilentlyContinue).SessionId } catch {}
        $line = "[$([DateTimeOffset]::Now.ToString('o'))] [$Level] [PID $PID] [Session $session] $Msg"
        $logDir = Split-Path -Parent -Path $script:SplashLogPath
        if (-not (Test-Path -LiteralPath $logDir)) {
            New-Item -ItemType Directory -Path $logDir -Force -ErrorAction SilentlyContinue | Out-Null
        }
        Add-Content -LiteralPath $script:SplashLogPath -Value $line -Encoding UTF8 -ErrorAction SilentlyContinue
    } catch { }
}

# =====================================================================
# 2300 Phase 0: OOBE-suppression diagnostics + central toggle reader.
# =====================================================================
# Dedicated log so the suppression layers can be bisected in the field
# without wading through the (very busy) splash-ui.log. Modeled on
# Write-SplashLog. Best-effort; a logging failure can never crash the splash.
$script:SplashSuppressionLogPath = 'C:\Windows\Setup\FirstBase\Logs\splash-oobe-suppression.log'
# Config file dropped by SetupComplete.cmd so a field tech can flip a layer without a rebuild.
$script:FbSplashSuppressionConfigFile = 'C:\Windows\Setup\FirstBase\splash-suppression.cfg'
# Seal-window guard: the update loop writes this the moment it enters Invoke-FbOobeHandoff. While it exists,
# Layer 2 (kill OOBE) is HALTED regardless of toggles so the real customer OOBE the loop is about to regenerate
# via sysprep /oobe is never killed. Path is shared with Invoke-WindowsUpdateLoop.ps1 ($FbSealWindowGuardPath).
$script:FbSplashSealWindowGuardPath = 'C:\ProgramData\FirstBase\.oobe-seal-window'
# Per-boot Layer 2 kill accounting (respawn is expected; back off after repeated kills of the same host).
$script:FbSplashOobeKillCount = 0
$script:FbSplashOobeKillByProc = @{}
$script:FbSplashOobeKillLastUtc = $null
# 2304: raise the per-boot/per-proc kill ceiling. Field evidence (bundles 1412/1433): killing the OOBE host that holds
# the foreground is the ONLY primitive that reliably surfaces the splash (post-kill SetForegroundWindow returns True
# gle=0 every time; the self-window min/restore reclaim does not). The old ceiling of 3 throttled the kill to ~1/20s
# during the WWAHost respawn storm, so the splash sat behind OOBE between kills. 30 lets the proven kill+activate keep
# firing through the ~1 min storm (it subsides once updates progress). Still bounded, still per-20s, still seal-gated.
$script:FbSplashOobeKillCeiling = 30
$script:FbSplashSuppressionConfigCache = $null
$script:FbSplashSuppressionConfigCacheUtc = $null
# 2303: pre-initialize so the per-tick Layer 1 re-apply state compare (Invoke-FbSplashReapplyForegroundLockTimeoutZeroTick)
# does not throw under StrictMode (reading an unset $script: variable is prohibited).
$script:FbSplashFglockTickState = ''

function Write-SplashSuppressionLog {
    param([string]$Msg, [string]$Level = 'INFO')
    try {
        $session = 'unknown'
        try { $session = (Get-Process -Id $PID -ErrorAction SilentlyContinue).SessionId } catch {}
        $line = "[$([DateTimeOffset]::Now.ToString('o'))] [$Level] [PID $PID] [Session $session] $Msg"
        $logDir = Split-Path -Parent -Path $script:SplashSuppressionLogPath
        if (-not (Test-Path -LiteralPath $logDir)) {
            New-Item -ItemType Directory -Path $logDir -Force -ErrorAction SilentlyContinue | Out-Null
        }
        Add-Content -LiteralPath $script:SplashSuppressionLogPath -Value $line -Encoding UTF8 -ErrorAction SilentlyContinue
    } catch { }
}

function Get-FbSplashSuppressionConfigValue {
    # Env var wins; else config-file key=value line; else $null. Case-insensitive key match.
    param([string]$Name)
    try {
        $envVal = [System.Environment]::GetEnvironmentVariable($Name)
        if (-not [string]::IsNullOrWhiteSpace($envVal)) { return $envVal.Trim() }
    } catch {}
    try {
        if ($script:FbSplashSuppressionConfigFileLines) {
            foreach ($ln in $script:FbSplashSuppressionConfigFileLines) {
                $t = ([string]$ln).Trim()
                if ($t.Length -eq 0 -or $t.StartsWith('#') -or $t.StartsWith(';')) { continue }
                $eq = $t.IndexOf('=')
                if ($eq -lt 1) { continue }
                $k = $t.Substring(0, $eq).Trim()
                if ($k -ieq $Name) { return $t.Substring($eq + 1).Trim() }
            }
        }
    } catch {}
    return $null
}

function Test-FbSplashSuppressionTruthy {
    param([string]$Value, [bool]$Default)
    if ($null -eq $Value -or $Value.Length -eq 0) { return $Default }
    switch -Regex ($Value.Trim().ToLowerInvariant()) {
        '^(1|true|yes|on|enable[d]?)$'  { return $true }
        '^(0|false|no|off|disable[d]?)$' { return $false }
        default { return $Default }
    }
}

function Get-FbSplashSuppressionConfig {
    # Central toggle surface. Reads env vars first, then the SetupComplete-dropped config file.
    # Cached ~3s so per-tick reads are cheap while still letting a tech flip a value mid-run.
    try {
        if ($null -ne $script:FbSplashSuppressionConfigCacheUtc) {
            $ageMs = ([System.DateTimeOffset]::UtcNow - $script:FbSplashSuppressionConfigCacheUtc).TotalMilliseconds
            if ($ageMs -lt 3000 -and $null -ne $script:FbSplashSuppressionConfigCache) {
                return $script:FbSplashSuppressionConfigCache
            }
        }
    } catch {}
    $script:FbSplashSuppressionConfigFileLines = $null
    try {
        if (Test-Path -LiteralPath $script:FbSplashSuppressionConfigFile) {
            $script:FbSplashSuppressionConfigFileLines = @(Get-Content -LiteralPath $script:FbSplashSuppressionConfigFile -ErrorAction SilentlyContinue)
        }
    } catch {}
    $globalDisable = Test-FbSplashSuppressionTruthy (Get-FbSplashSuppressionConfigValue 'FIRSTBASE_SPLASH_SUPPRESSION_DISABLE') $false
    $cfg = [pscustomobject]@{
        GlobalDisable = $globalDisable
        # Layer 1 fglock: default ON (low-risk root-cause fix).
        Fglock    = (-not $globalDisable) -and (Test-FbSplashSuppressionTruthy (Get-FbSplashSuppressionConfigValue 'FIRSTBASE_SPLASH_FGLOCK') $true)
        # Layer 2 killoobe: default OFF (opt-in).
        KillOobe  = (-not $globalDisable) -and (Test-FbSplashSuppressionTruthy (Get-FbSplashSuppressionConfigValue 'FIRSTBASE_SPLASH_KILL_OOBE') $false)
        # Layer 3 shell: default OFF (most invasive; opt-in). Read for diagnostics only in the splash.
        Shell     = (-not $globalDisable) -and (Test-FbSplashSuppressionTruthy (Get-FbSplashSuppressionConfigValue 'FIRSTBASE_SPLASH_SHELL') $false)
        # Layer 4 oobeflags: default OFF (opt-in). Acted on by the loop; read for diagnostics in the splash.
        OobeFlags = (-not $globalDisable) -and (Test-FbSplashSuppressionTruthy (Get-FbSplashSuppressionConfigValue 'FIRSTBASE_SPLASH_OOBE_FLAGS') $false)
    }
    $script:FbSplashSuppressionConfigCache = $cfg
    $script:FbSplashSuppressionConfigCacheUtc = [System.DateTimeOffset]::UtcNow
    return $cfg
}

function Test-FbSplashSealWindowActive {
    # Seal-window guard: loop wrote the marker at Invoke-FbOobeHandoff start. ALWAYS halts Layer 2 regardless of toggles.
    try { return (Test-Path -LiteralPath $script:FbSplashSealWindowGuardPath) } catch { return $false }
}

function Get-FbSplashCurrentForegroundLockTimeout {
    # Diagnostics: current SPI_GETFOREGROUNDLOCKTIMEOUT (ms). Returns -1 on failure.
    try {
        try { $null = [FbSplashWin32Z] } catch { return -1 }
        $val = [uint32]0
        $ok = [FbSplashWin32Z]::SystemParametersInfoGetUint([FbSplashWin32Z]::SPI_GETFOREGROUNDLOCKTIMEOUT, 0, [ref]$val, 0)
        if ($ok) { return [int]$val }
        return -1
    } catch { return -1 }
}

function Invoke-FbSplashApplyForegroundLockTimeoutZero {
    # 2300 Layer 1 (fglock): drop the foreground lock timeout to 0 for this session so SetForegroundWindow is honored
    # without recent input. Gated by config (default ON). Wrapped so a native failure can never crash the splash.
    try {
        $cfg = Get-FbSplashSuppressionConfig
        if (-not $cfg.Fglock) {
            Write-SplashSuppressionLog '2300 Layer1 fglock: DISABLED (FIRSTBASE_SPLASH_FGLOCK off or global disable); leaving ForegroundLockTimeout unchanged.'
            return
        }
        try { $null = [FbSplashWin32Z] } catch { Write-SplashSuppressionLog '2300 Layer1 fglock: FbSplashWin32Z unavailable; skipping.' 'WARN'; return }
        $before = Get-FbSplashCurrentForegroundLockTimeout
        # 2303: pvParam carries the value (uiParam is ignored) - [IntPtr]::Zero is the DWORD value 0, which is the
        # documented-correct call. NOTE (cosmetic): on Windows build 26100 this SPI SET returns ERROR_INVALID_PARAMETER
        # (gle=87) regardless of marshaling (IntPtr/UIntPtr), flags (0 / SENDWININICHANGE / UPDATEINIFILE), or value -
        # the OS refuses the runtime change here. This is harmless: SetupComplete's registry seed (ForegroundLockTimeout=0)
        # is what actually clears the lock for the session (field box 1253 shows fgLockTimeout=0ms). We keep the call +
        # gle logging for telemetry; the real residual blocker is the SetForegroundWindow activation privilege (see 2303 Fix 1).
        $ok = [FbSplashWin32Z]::SystemParametersInfoSet([FbSplashWin32Z]::SPI_SETFOREGROUNDLOCKTIMEOUT, 0, [IntPtr]::Zero, [FbSplashWin32Z]::SPIF_SENDWININICHANGE)
        $gle = [Runtime.InteropServices.Marshal]::GetLastWin32Error()
        $after = Get-FbSplashCurrentForegroundLockTimeout
        Write-SplashSuppressionLog ("2300 Layer1 fglock: SystemParametersInfo(SPI_SETFOREGROUNDLOCKTIMEOUT=0) ok={0} gle={1} before={2}ms after={3}ms" -f $ok, $gle, $before, $after)
    } catch {
        try { Write-SplashSuppressionLog ("2300 Layer1 fglock: EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch {}
    }
}

function Invoke-FbSplashReapplyForegroundLockTimeoutZeroTick {
    # 2302 Layer 1 re-apply: OOBE/CloudExperienceHost can re-force ForegroundLockTimeout back to 0x7FFFFFFF after our
    # startup set, so re-issue SPI_SETFOREGROUNDLOCKTIMEOUT=0 on every refresh tick to keep the reclaim path viable.
    # Only runs when Layer 1 (fglock) is enabled. Fully wrapped so it can never throw out of the tick. To avoid
    # spamming the ~1.5s tick log, logs only when the (ok, gle, after) tuple changes from the last observed state.
    param([bool]$Enabled)
    try {
        if (-not $Enabled) { return }
        try { $null = [FbSplashWin32Z] } catch { return }
        $ok = [FbSplashWin32Z]::SystemParametersInfoSet([FbSplashWin32Z]::SPI_SETFOREGROUNDLOCKTIMEOUT, 0, [IntPtr]::Zero, [FbSplashWin32Z]::SPIF_SENDWININICHANGE)
        $gle = [Runtime.InteropServices.Marshal]::GetLastWin32Error()
        $after = Get-FbSplashCurrentForegroundLockTimeout
        $stateKey = ("{0}|{1}|{2}" -f $ok, $gle, $after)
        if ($script:FbSplashFglockTickState -ne $stateKey) {
            $script:FbSplashFglockTickState = $stateKey
            Write-SplashSuppressionLog ("2302 Layer1 fglock re-apply (tick, state-change): SystemParametersInfo(SPI_SETFOREGROUNDLOCKTIMEOUT=0) ok={0} gle={1} after={2}ms" -f $ok, $gle, $after)
        }
    } catch {
        try { Write-SplashSuppressionLog ("2302 Layer1 fglock re-apply: EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch {}
    }
}

function Invoke-FbSplashKillOobeForegroundHost {
    # 2300 Layer 2 (killoobe): when an OOBE-family host holds the foreground, Stop-Process -Force it (NEVER minimize -
    # minimizing WWAHost CoreWindow caused the 2214g/2214h black screen). Gated by FIRSTBASE_SPLASH_KILL_OOBE (default OFF)
    # AND halted by the seal-window guard. Per-boot kill counter + per-proc backoff (respawn is expected).
    param([bool]$Enabled, [Nullable[int]]$SimulatedPid = $null)
    try {
        if (-not $Enabled) { return }
        if (Test-FbSplashSealWindowActive) {
            Write-SplashSuppressionLog '2300 Layer2 killoobe: seal-window guard active; NOT killing OOBE (loop is regenerating real customer OOBE).'
            return
        }
        try { $null = [FbSplashWin32Z] } catch { return }
        $fg = [FbSplashWin32Z]::GetForegroundWindow()
        if ($fg -eq [IntPtr]::Zero) { return }
        if ($script:SplashNativeHwnd -ne $null -and $fg -eq $script:SplashNativeHwnd) { return }
        $pidFg = [uint32]0
        [void][FbSplashWin32Z]::GetWindowThreadProcessId($fg, [ref]$pidFg)
        if ($pidFg -eq 0) { return }
        $procName = ''
        try {
            $p = Get-Process -Id ([int]$pidFg) -ErrorAction SilentlyContinue
            if ($p) { $procName = $p.ProcessName }
        } catch {}
        $pnLower = ($procName + '.exe').ToLowerInvariant()
        $isOobeFg = ($pnLower -eq 'oobeldr.exe') -or ($pnLower -eq 'useroobebroker.exe') -or ($pnLower -eq 'cloudexperiencehost.exe') -or ($pnLower -eq 'shellexperiencehost.exe') -or ($pnLower -eq 'applicationframehost.exe') -or ($pnLower -eq 'wwahost.exe')
        # -SimulateOobeForeground: treat the dummy window's pid as the target so the kill path runs off-hardware.
        if (-not $isOobeFg -and $null -ne $SimulatedPid -and [int]$pidFg -eq [int]$SimulatedPid) { $isOobeFg = $true; $pnLower = 'simulated-oobe' }
        if (-not $isOobeFg) { return }
        # Backoff: after FbSplashOobeKillCeiling kills of the same proc name within 20s, skip (2304: raised 3->30 so the
        # proven kill+activate keeps surfacing the splash through the respawn storm instead of throttling to ~1/20s).
        $now = [System.DateTimeOffset]::UtcNow
        $priorForProc = 0
        try { if ($script:FbSplashOobeKillByProc.ContainsKey($pnLower)) { $priorForProc = [int]$script:FbSplashOobeKillByProc[$pnLower] } } catch {}
        if ($priorForProc -ge $script:FbSplashOobeKillCeiling -and $null -ne $script:FbSplashOobeKillLastUtc) {
            if (($now - $script:FbSplashOobeKillLastUtc).TotalSeconds -lt 20) {
                Write-SplashSuppressionLog ("2300 Layer2 killoobe: backoff - {0} killed {1}x this boot within 20s; skipping (relying on topmost stack)." -f $pnLower, $priorForProc)
                return
            }
        }
        try {
            Stop-Process -Id ([int]$pidFg) -Force -ErrorAction Stop
            $script:FbSplashOobeKillCount++
            try { $script:FbSplashOobeKillByProc[$pnLower] = ($priorForProc + 1) } catch {}
            $script:FbSplashOobeKillLastUtc = $now
            Write-SplashSuppressionLog ("2300 Layer2 killoobe: Stop-Process -Force proc={0} pid={1} (killNo={2} thisProc={3}); respawn expected." -f $pnLower, $pidFg, $script:FbSplashOobeKillCount, ($priorForProc + 1))
            # 2303 Fix 2: couple kill->activate in the SAME tick so the splash claims the foreground in the brief
            # window before the OOBE host respawns (field bundle 1253: respawn re-grabbed FG before the next UI tick).
            # Seal-safe: acts only on the splash's own window/input; the kill above is already seal-gated + backoff-limited.
            [void](Invoke-FbSplashForceSelfForeground -Reason 'post-kill')
        } catch {
            Write-SplashSuppressionLog ("2300 Layer2 killoobe: Stop-Process proc={0} pid={1} FAILED: {2}" -f $pnLower, $pidFg, $_.Exception.Message) 'WARN'
        }
    } catch {
        try { Write-SplashSuppressionLog ("2300 Layer2 killoobe: EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch {}
    }
}

function Invoke-FbSplashSuppressionDiagnosticsAndKillTick {
    # 2300 Phase 0 diagnostics (ALWAYS ON) + Layer 2 kill hook. Called from the 1.5s refresh timer (and the preview
    # simulate timer). Logs fg pid/proc/class, splash hwnd, current ForegroundLockTimeout, enabled layers, and which
    # layer acted. Entirely wrapped so it can never crash the splash tick.
    try {
        $cfg = Get-FbSplashSuppressionConfig
        # 2302: re-apply Layer 1 (fglock) every tick so an OOBE-forced ForegroundLockTimeout can't defeat the reclaim.
        Invoke-FbSplashReapplyForegroundLockTimeoutZeroTick -Enabled ([bool]$cfg.Fglock)
        $fgLine = 'fg=(none)'
        $fgPid = 0
        try {
            try { $null = [FbSplashWin32Z] } catch {}
            $fg = [FbSplashWin32Z]::GetForegroundWindow()
            if ($fg -ne [IntPtr]::Zero) {
                $pidFg = [uint32]0
                [void][FbSplashWin32Z]::GetWindowThreadProcessId($fg, [ref]$pidFg)
                $fgPid = [int]$pidFg
                $pn = 'unknown'
                try { $p = Get-Process -Id ([int]$pidFg) -ErrorAction SilentlyContinue; if ($p) { $pn = $p.ProcessName + '.exe' } } catch {}
                $sb = New-Object System.Text.StringBuilder 256
                [void][FbSplashWin32Z]::GetClassName($fg, $sb, 256)
                $fgLine = ('fg={0} class={1} pid={2}' -f $pn, $sb.ToString(), $pidFg)
            }
        } catch { $fgLine = 'fg=(error)' }
        $sealActive = Test-FbSplashSealWindowActive
        $fglt = Get-FbSplashCurrentForegroundLockTimeout
        Write-SplashSuppressionLog ("2300 tick: {0} splashHwnd={1} fgLockTimeout={2}ms layers[fglock={3} killoobe={4} shell={5} oobeflags={6} globalDisable={7}] seal={8}" -f `
            $fgLine, $script:SplashNativeHwnd, $fglt, $cfg.Fglock, $cfg.KillOobe, $cfg.Shell, $cfg.OobeFlags, $cfg.GlobalDisable, $sealActive)
        # Layer 2 kill (gated by toggle + seal guard inside the helper).
        $simPid = $null
        if ($script:SimulateOobeForeground -and $null -ne $script:FbSimulatedOobePid) { $simPid = [int]$script:FbSimulatedOobePid }
        Invoke-FbSplashKillOobeForegroundHost -Enabled ([bool]$cfg.KillOobe) -SimulatedPid $simPid
    } catch {
        try { Write-SplashSuppressionLog ("2300 tick: EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch {}
    }
}

function Start-FbSplashSimulatedOobeForeground {
    # 2300 Phase 0 test hook (-Preview -SimulateOobeForeground): spawn a dummy borderless topmost window in a child
    # powershell so the fg-reclaim / Layer 2 kill logic has a real foreground target off-hardware. Best-effort.
    if (-not $script:SimulateOobeForeground) { return }
    try {
        $sim = @'
Add-Type -AssemblyName PresentationFramework
$w = New-Object System.Windows.Window
$w.Title = 'SIMULATED OOBE (FirstBase test)'
$w.WindowStyle = 'None'; $w.WindowState = 'Maximized'; $w.Topmost = $true; $w.Background = 'Black'
$tb = New-Object System.Windows.Controls.TextBlock
$tb.Text = 'SIMULATED OOBE FOREGROUND'; $tb.Foreground = 'White'; $tb.FontSize = 42
$tb.HorizontalAlignment = 'Center'; $tb.VerticalAlignment = 'Center'
$w.Content = $tb
[void]$w.ShowDialog()
'@
        $tmp = Join-Path $env:TEMP ("fb-sim-oobe-{0}.ps1" -f ([guid]::NewGuid().ToString('N')))
        Set-Content -LiteralPath $tmp -Value $sim -Encoding UTF8
        $proc = Start-Process -FilePath 'powershell.exe' -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Hidden', '-File', $tmp) -PassThru
        if ($proc) {
            $script:FbSimulatedOobePid = $proc.Id
            $script:FbSimulatedOobeScript = $tmp
            Write-SplashSuppressionLog ("2300 SimulateOobeForeground: spawned dummy topmost window pid={0} (script={1})" -f $proc.Id, $tmp)
        }
    } catch {
        try { Write-SplashSuppressionLog ("2300 SimulateOobeForeground: spawn EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch {}
    }
}

trap {
    try {
        $msg = ("TRAP: {0}: {1} | StackTrace: {2}" -f $_.Exception.GetType().FullName, $_.Exception.Message, $_.ScriptStackTrace)
        Write-SplashLog $msg 'ERROR'
    } catch { }
    continue
}

# 2256/2295: Post-delivery / post-operator seal - never spin WPF (RunOnce / stale launcher can still invoke this script).
# Off-device -Preview skips these gates so visual tests can open the splash on a technician PC.
if (-not $script:Preview) {
    $fb2295LegacyDeliveryStarted = $false
    if (Test-Path -LiteralPath $FbSplashPipelineCompletedMarker) {
        try {
            $fb2295LegacyTxt = [string](Get-Content -LiteralPath $FbSplashPipelineCompletedMarker -Raw -ErrorAction SilentlyContinue)
            $fb2295LegacyDeliveryStarted = ($fb2295LegacyTxt -match 'Pipeline started')
        } catch {}
    }
    if ((Test-Path -LiteralPath $FbSplashPipelineCompletedMarker) -or (Test-Path -LiteralPath $FbSplashDeliveryStartedMarker) -or $fb2295LegacyDeliveryStarted -or (Test-Path -LiteralPath $FbSealedMarker)) {
        Write-SplashLog '2295: delivery-started, pipeline-completed, or sealed present; exiting before WPF.' 'INFO'
        exit 0
    }
    # 2305: seal-window teardown - the update loop has entered the OOBE handoff seal window; never spin up the splash on
    # top of the real customer OOBE. Exit before building WPF.
    if (Test-Path -LiteralPath $FbSplashSealTeardownMarker) {
        Write-SplashLog '2305: seal-window teardown marker present at startup; exiting before WPF so the customer OOBE is clean.' 'INFO'
        exit 0
    }
}

Write-SplashLog ("STARTUP: Show-UpdateProgress.ps1 entered (product={0} script={1} payload={2})" -f $FirstBaseProductVersion, $script:ThisScriptVersion, $FirstBasePayloadRevision)
Write-SplashLog ("STARTUP: PSVersion={0} CLR={1} Host={2}" -f $PSVersionTable.PSVersion, $PSVersionTable.CLRVersion, $Host.Name)

try {
    Write-SplashLog "Loading PresentationFramework, PresentationCore, WindowsBase..."
    Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase -ErrorAction Stop
    Write-SplashLog "PresentationFramework loaded successfully"
} catch {
    Write-SplashLog "FAILED to load PresentationFramework: $($_.Exception.Message)" 'ERROR'
    throw
}

# 2213z + 2214a + 2214b: Win32 z-order  -  WPF Topmost alone loses to OOBE shell topmost.
try {
    Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
using System.Text;
public static class FbSplashWin32Z {
    public static readonly IntPtr HWND_TOPMOST = new IntPtr(-1);
    public static readonly IntPtr HWND_NOTOPMOST = new IntPtr(-2);
    public const uint SWP_NOSIZE = 0x0001;
    public const uint SWP_NOMOVE = 0x0002;
    public const uint SWP_NOZORDER = 0x0004;
    public const uint SWP_NOACTIVATE = 0x0010;
    public const uint SWP_SHOWWINDOW = 0x0040;
    [DllImport("user32.dll")]
    public static extern int GetSystemMetrics(int nIndex);
    public const int GWL_EXSTYLE = -20;
    public const long WS_EX_TOPMOST = 0x00000008L;
    [DllImport("user32.dll", SetLastError = true)]
    public static extern bool SetWindowPos(IntPtr hWnd, IntPtr hWndInsertAfter, int X, int Y, int cx, int cy, uint uFlags);
    [DllImport("user32.dll")]
    public static extern bool AllowSetForegroundWindow(uint dwProcessId);
    [DllImport("user32.dll")]
    public static extern bool SetForegroundWindow(IntPtr hWnd);
    [DllImport("user32.dll", EntryPoint = "GetWindowLongPtr", SetLastError = true)]
    public static extern IntPtr GetWindowLongPtr(IntPtr hWnd, int nIndex);
    [DllImport("user32.dll", EntryPoint = "SetWindowLongPtr", SetLastError = true)]
    public static extern IntPtr SetWindowLongPtr(IntPtr hWnd, int nIndex, IntPtr dwNewLong);
    [DllImport("user32.dll")]
    public static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll")]
    public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)]
    public static extern int GetClassName(IntPtr hWnd, StringBuilder lpClassName, int nMaxCount);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)]
    public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);
    [DllImport("user32.dll", SetLastError = true)]
    public static extern bool AttachThreadInput(uint idAttach, uint idAttachTo, bool fAttach);
    [DllImport("kernel32.dll")]
    public static extern uint GetCurrentThreadId();
    [DllImport("user32.dll")]
    public static extern bool BringWindowToTop(IntPtr hWnd);
    // 2304: the semi-documented API the Alt+Tab shell itself uses; frequently confers the activation SetForegroundWindow
    // is denied. Seal-safe when called on our own splash hwnd only.
    [DllImport("user32.dll", SetLastError = true)]
    public static extern void SwitchToThisWindow(IntPtr hWnd, bool fUnknown);
    public const int SW_HIDE = 0;
    public const int SW_SHOW = 5;
    public const int SW_MINIMIZE = 6;
    public const int SW_RESTORE = 9;
    [DllImport("user32.dll")]
    public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
    [DllImport("user32.dll")]
    public static extern bool IsIconic(IntPtr hWnd);
    [DllImport("user32.dll")]
    public static extern bool IsWindow(IntPtr hWnd);
    [DllImport("user32.dll")]
    public static extern IntPtr GetParent(IntPtr hWnd);
    [DllImport("user32.dll")]
    public static extern IntPtr GetAncestor(IntPtr hwnd, uint gaFlags);
    public const uint GA_ROOT = 2;
    [DllImport("user32.dll")]
    public static extern bool IsWindowVisible(IntPtr hWnd);
    [DllImport("user32.dll")]
    public static extern IntPtr GetWindow(IntPtr hWnd, uint uCmd);
    public const uint GW_HWNDPREV = 3;
    public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
    [DllImport("user32.dll")]
    public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
    public static System.Collections.Generic.HashSet<uint> Oobe2214cPidSet = new System.Collections.Generic.HashSet<uint>();
    public static System.Collections.Generic.List<IntPtr> Oobe2214cEnumBuf = new System.Collections.Generic.List<IntPtr>();
    public static IntPtr Oobe2214cExclude = IntPtr.Zero;
    public static void Oobe2214cSetPids(uint[] pids) {
        Oobe2214cPidSet.Clear();
        if (pids == null) { return; }
        foreach (var p in pids) { Oobe2214cPidSet.Add(p); }
    }
    public static bool Oobe2214cEnumCb(IntPtr hWnd, IntPtr lParam) {
        if (GetParent(hWnd) != IntPtr.Zero) { return true; }
        uint pid = 0;
        GetWindowThreadProcessId(hWnd, out pid);
        if (!Oobe2214cPidSet.Contains(pid)) { return true; }
        if (hWnd == Oobe2214cExclude) { return true; }
        if (!IsWindowVisible(hWnd)) { return true; }
        if (IsIconic(hWnd)) { return true; }
        Oobe2214cEnumBuf.Add(hWnd);
        return true;
    }
    public static IntPtr[] Oobe2214cCollectVisibleTopLevel(IntPtr excludeHwnd) {
        Oobe2214cEnumBuf.Clear();
        Oobe2214cExclude = excludeHwnd;
        EnumWindows(Oobe2214cEnumCb, IntPtr.Zero);
        return Oobe2214cEnumBuf.ToArray();
    }
    public static bool OobeChromeEnumCb(IntPtr hWnd, IntPtr lParam) {
        if (GetParent(hWnd) != IntPtr.Zero) { return true; }
        if (hWnd == Oobe2214cExclude) { return true; }
        if (!IsWindowVisible(hWnd)) { return true; }
        Oobe2214cEnumBuf.Add(hWnd);
        return true;
    }
    public static IntPtr[] OobeChromeCollectVisibleTopLevel(IntPtr excludeHwnd) {
        Oobe2214cEnumBuf.Clear();
        Oobe2214cExclude = excludeHwnd;
        EnumWindows(OobeChromeEnumCb, IntPtr.Zero);
        return Oobe2214cEnumBuf.ToArray();
    }
    [DllImport("kernel32.dll", EntryPoint = "SetLastError")]
    public static extern void FbSetLastError(uint dwErrCode);
    /// <summary>2214m: Clear last error, SetWindowPos(ooobe below splash), return Win32 error for field logs.</summary>
    public static bool Oobe2214mSetWindowPosZBehindSplash(IntPtr hWndOobe, IntPtr hWndSplash, uint swpFlags, out uint lastError) {
        FbSetLastError(0);
        bool ok = SetWindowPos(hWndOobe, hWndSplash, 0, 0, 0, 0, swpFlags);
        lastError = (uint)Marshal.GetLastWin32Error();
        return ok;
    }
