    // user input (the same activation provenance the operator's working Alt+Tab uses), which the inert VK_F15 did not.
    public const byte VK_MENU = 0x12;
    public const uint KEYEVENTF_KEYUP = 0x0002;
    [DllImport("user32.dll")]
    public static extern void keybd_event(byte bVk, byte bScan, uint dwFlags, System.UIntPtr dwExtraInfo);
    // 2300 Layer 1 fglock: remove the OOBE foreground lock for this session so the reclaim / 2296 nudge path succeeds
    // every tick (root cause of "only works after Shift+F10"). SPI_SETFOREGROUNDLOCKTIMEOUT passes the timeout in pvParam
    // (DWORD cast to PVOID); pass IntPtr.Zero to set 0ms. The Get variant returns the current value via ref for diagnostics.
    public const uint SPI_GETFOREGROUNDLOCKTIMEOUT = 0x2000;
    public const uint SPI_SETFOREGROUNDLOCKTIMEOUT = 0x2001;
    public const uint SPIF_UPDATEINIFILE = 0x01;
    public const uint SPIF_SENDWININICHANGE = 0x02;
    [DllImport("user32.dll", SetLastError = true, EntryPoint = "SystemParametersInfoW")]
    public static extern bool SystemParametersInfoSet(uint uiAction, uint uiParam, IntPtr pvParam, uint fWinIni);
    [DllImport("user32.dll", SetLastError = true, EntryPoint = "SystemParametersInfoW")]
    public static extern bool SystemParametersInfoGetUint(uint uiAction, uint uiParam, ref uint pvParam, uint fWinIni);
}
