                                    <StackPanel Orientation="Horizontal">
                                        <TextBlock Name="PassStatusLabel" Text="STATUS" FontSize="11" FontWeight="Bold" Foreground="#FFFF9800" VerticalAlignment="Center" Margin="0,0,8,0"/>
