                                    </StackPanel>
                                </Border>
                                <Border Name="DevBuildIndicator" VerticalAlignment="Center" Padding="12,4,12,4" Background="#FF2A0A0A" BorderBrush="#FFEF5350" BorderThickness="1" CornerRadius="14" Visibility="Collapsed">
