                    <Border Name="HandoffCopyHost" Visibility="Collapsed" Background="#FF071428" Padding="36,28">
                        <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center" MaxWidth="820">
                            <TextBlock Name="HandoffEyebrowText" Text="OOBE HANDOFF" Foreground="#FF22D3EE" FontSize="13" FontWeight="Bold" HorizontalAlignment="Center"/>
                            <TextBlock Name="HandoffHeaderText" Text="Preparing hardware checks" Foreground="White" FontSize="26" FontWeight="SemiBold" TextAlignment="Center" TextWrapping="Wrap" Margin="0,12,0,10"/>
                            <TextBlock Name="HandoffDetailText" Text="Updates are complete. FirstBase will verify Wi-Fi, camera, and sound, then open YouTube or Settings." Foreground="#FF87CEEB" FontSize="16" TextAlignment="Center" TextWrapping="Wrap"/>
                        </StackPanel>
                    </Border>
                    </Grid>
                </Grid>
            </Border>
        </Grid>
    </Grid>
    </Viewbox>
    </Grid>
</Window>
'@

try {
    Write-SplashLog "Parsing XAML via XmlNodeReader + XamlReader.Load..."
    $reader  = New-Object System.Xml.XmlNodeReader $xaml
    $window  = [Windows.Markup.XamlReader]::Load($reader)
    Write-SplashLog "XAML parsed successfully, window object created"
} catch {
    Write-SplashLog "FAILED to parse XAML: $($_.Exception.GetType().FullName): $($_.Exception.Message)" 'ERROR'
    throw
}

$passText             = $window.FindName('PassText')
$passStatusHost       = $window.FindName('PassStatusHost')
$passStatusLabel      = $window.FindName('PassStatusLabel')
$rebootCountHost      = $window.FindName('RebootCountHost')
$rebootCountText      = $window.FindName('RebootCountText')
$rebootCountLabel     = $window.FindName('RebootCountLabel')
$totalElapsedText     = $window.FindName('TotalElapsedText')
$totalElapsedHost     = $window.FindName('TotalElapsedHost')
$totalElapsedLabel    = $window.FindName('TotalElapsedLabel')
$elapsedText          = $window.FindName('ElapsedText')
$elapsedHost          = $window.FindName('ElapsedHost')
$warningText          = $window.FindName('WarningText')
$updatesList          = $window.FindName('UpdatesList')
$updatesPlaceholder   = $window.FindName('UpdatesPlaceholder')
$handoffCopyHost      = $window.FindName('HandoffCopyHost')
$splashRoot           = $window.FindName('SplashRoot')
$designCanvas         = $window.FindName('DesignCanvas')
$handoffEyebrowText   = $window.FindName('HandoffEyebrowText')
$handoffHeaderText    = $window.FindName('HandoffHeaderText')
$handoffDetailText    = $window.FindName('HandoffDetailText')
$script:FbSplashHandoffLayoutActive = $false
$script:FbSplashPulseRunning = $false
$script:FbSplashCompletedLatch = $false
$script:FbSplashLastStatusUpdatedAt = ''
$script:FbSplashHandoffHostStarted = $false
$script:FbSplashClosingForHandoffSwitch = $false
$topmostIndicator     = $window.FindName('TopmostIndicator')
$topmostIndicatorText = $window.FindName('TopmostIndicatorText')
$devBuildIndicator    = $window.FindName('DevBuildIndicator')
$devBuildIndicatorText = $window.FindName('DevBuildIndicatorText')
try {
    if ($updatesList) { $updatesList.ItemsSource = @() }
} catch {}
function Get-FbSplashBgKind {
    param(
        [string]$Text,
        [string]$Phase = '',
        [string]$Message = ''
    )
    $blob = ('{0} {1} {2}' -f $Phase, $Message, $Text)
    if ($blob -match '(?i)escape valve|apply failed|dump-worthy|futile') { return 'error' }
    if ($Phase -match '(?i)error|fail') { return 'error' }
    if ($Text -match '(?i)^failed|error') { return 'error' }
    if ($Message -match '(?i)failed|error') { return 'error' }
    if ($Phase -match '(?i)^reboot|manualrestart') { return 'warn' }
    if ($Text -match '(?i)restart this pc|restarting to continue|hold the power') { return 'warn' }
    if ($blob -match '(?i)stalled|wedge') { return 'warn' }
    return 'normal'
}

function Set-FbSplashHealthBackground {
    param(
        [string]$Text,
        [string]$Phase = '',
        [string]$Message = ''
    )
    $kind = Get-FbSplashBgKind -Text $Text -Phase $Phase -Message $Message
    if ($script:FbSplashBgKind -eq $kind) { return }
    $script:FbSplashBgKind = $kind
    $hex = '#FF000000'
    if ($kind -eq 'error') { $hex = '#FF4A0C0C' }
    elseif ($kind -eq 'warn') { $hex = '#FF4A2A08' }
    try {
        $brush = [System.Windows.Media.BrushConverter]::new().ConvertFromString($hex)
        if ($window) { $window.Background = $brush }
        if ($splashRoot) { $splashRoot.Background = $brush }
        if ($designCanvas) { $designCanvas.Background = $brush }
        Write-SplashLog ("splash BG kind={0} hex={1}" -f $kind, $hex)
    } catch {}
}

function Get-FbSplashStatusAccent {
    param([string]$Text)
    $t = if ($null -eq $Text) { '' } else { $Text.Trim().ToLowerInvariant() }
    # Phase-coded colors (aligned with row StatusColor values where possible).
    if ($t -match 'failed|error') { return '#FFEF5350' }
    if ($t -match 'handoff|oobe') { return '#FF22D3EE' }
    if ($t -match 'complete|finished|done') { return '#FF66BB6A' }
    if ($t -match 'finishing') { return '#FF81C784' }
    if ($t -match 'pending restart|awaiting|sysprep|reboot|power') { return '#FFB388FF' }
    if ($t -match 'retry next boot') { return '#FFFF8A65' }
    if ($t -match 'retry') { return '#FFFF8A65' }
    if ($t -match 'network|waiting for network') { return '#FFF0C14B' }
    # Screenshot STATUS pill is orange for the live update pass (download and/or install).
    if ($t -match 'download' -or $t -match 'install') { return '#FFFF9800' }
    if ($t -match 'checking|found|preparing') { return '#FF22D3EE' }
    if ($t -match 'getting ready|updates') { return '#FF22D3EE' }
    return '#FF6B8CB0'
}

function Test-FbSplashStatusIsActive {
    param([string]$Text)
    $t = if ($null -eq $Text) { '' } else { $Text.Trim().ToLowerInvariant() }
    return [bool]($t -match 'download|install|checking|retrying|getting ready|preparing|found|finishing|handoff|applying|restart')
}

function Convert-FbSplashTextToAscii {
    # STATUS / activity / row copy must stay ASCII. UTF-8 no-BOM em-dashes
    # (E2 80 94) decode as a closing quote under Windows-1252 and show as
    # garbage in the splash pill.
    param([string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text)) { return '' }
    $t = [string]$Text
    $t = $t.Replace(([char]0x2014).ToString(), '-')
    $t = $t.Replace(([char]0x2013).ToString(), '-')
    $t = $t.Replace(([char]0x2212).ToString(), '-')
    $t = $t.Replace(([char]0x00AD).ToString(), '')
    $t = $t.Replace(([char]0x2018).ToString(), "'")
    $t = $t.Replace(([char]0x2019).ToString(), "'")
    $t = $t.Replace(([char]0x201C).ToString(), '"')
    $t = $t.Replace(([char]0x201D).ToString(), '"')
    $t = $t.Replace(([char]0x2026).ToString(), '...')
    $t = $t.Replace(([char]0x00A0).ToString(), ' ')
    $t = $t.Replace(([char]0x2122).ToString(), '')
    $t = $t.Replace(([char]0x00AE).ToString(), '')
    $sb = New-Object System.Text.StringBuilder
    foreach ($ch in $t.ToCharArray()) {
        $n = [int]$ch
        if ($n -eq 9 -or $n -eq 10 -or $n -eq 13 -or ($n -ge 32 -and $n -le 126)) {
            [void]$sb.Append($ch)
        }
    }
    return (($sb.ToString() -replace '\s{2,}', ' ').Trim())
}

function Set-FbSplashPassStatus {
    param(
        [string]$Text,
        [string]$Phase = '',
        [string]$Message = ''
    )
    if (-not $passText) { return }
    $Text = Convert-FbSplashTextToAscii -Text $Text
    $wantActive = Test-FbSplashStatusIsActive -Text $Text
    $textChanged = ($passText.Text -ne $Text)
    $passText.Text = $Text
    $accent = Get-FbSplashStatusAccent -Text $Text
    try {
        $brush = [System.Windows.Media.BrushConverter]::new().ConvertFromString($accent)
        $passText.Foreground = $brush
        if ($passStatusLabel) { $passStatusLabel.Foreground = $brush }
        if ($passStatusHost) {
            $passStatusHost.BorderBrush = $brush
        }
        try { Set-FbSplashHealthBackground -Text $Text -Phase $Phase -Message $Message } catch {}
    } catch {
        try { $passText.Foreground = [System.Windows.Media.Brushes]::LightSkyBlue } catch {}
    }
    try {
        $pulse = $window.TryFindResource('PassStatusPulse')
        if ($pulse -and $passStatusHost) {
            if ($wantActive) {
                # Do not Begin() every status poll - that restarts the pulse from
                # 0 and makes the STATUS pill hitch once a second.
                if (-not $script:FbSplashPulseRunning) {
                    $pulse.Begin($window, $true)
                    $script:FbSplashPulseRunning = $true
                }
            } else {
                if ($script:FbSplashPulseRunning -or $textChanged) {
                    try { $pulse.Stop($window) } catch {}
                    $script:FbSplashPulseRunning = $false
                    $passStatusHost.Opacity = 0.95
                }
            }
        }
    } catch {}
}

function Format-FbSplashDuration {
    param([TimeSpan]$Elapsed)
    $totalSec = [math]::Max(0, [long][math]::Floor($Elapsed.TotalSeconds))
    $h = [int][math]::Floor($totalSec / 3600)
    $m = [int][math]::Floor(($totalSec % 3600) / 60)
    $s = [int]($totalSec % 60)
    if ($h -ge 100) { return ('{0}:{1:D2}:{2:D2}' -f $h, $m, $s) }
    return ('{0:D2}:{1:D2}:{2:D2}' -f $h, $m, $s)
}

function Set-FbSplashElapsedDisplay {
    param([TimeSpan]$Elapsed)
    if (-not $elapsedText) { return }
    $elapsedText.Text = Format-FbSplashDuration -Elapsed $Elapsed
}

function Get-FbSplashPipelineStartTime {
    # Pipeline-wide start from wu-state.json StartTime (survives reboot).
    # Seed a one-shot marker if the loop has not written state yet.
    $marker = Join-Path $FbRoot 'wu-pipeline-started.utc'
    try {
        $statePath = Join-Path $FbRoot 'wu-state.json'
        if (Test-Path -LiteralPath $statePath) {
            $diskState = Get-Content -LiteralPath $statePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
            if ($diskState.PSObject.Properties.Name -contains 'StartTime' -and $diskState.StartTime) {
                $parsed = [datetime]::MinValue
                if ([datetime]::TryParse([string]$diskState.StartTime, [ref]$parsed)) {
                    try {
                        if (-not (Test-Path -LiteralPath $marker)) {
                            Set-Content -LiteralPath $marker -Value $parsed.ToUniversalTime().ToString('o') -Encoding ASCII -ErrorAction SilentlyContinue
                        }
                    } catch {}
                    return $parsed
                }
            }
        }
    } catch {}
    try {
        if (Test-Path -LiteralPath $marker) {
            $raw = (Get-Content -LiteralPath $marker -Raw -ErrorAction Stop).Trim()
            $parsed = [datetime]::MinValue
            if ($raw -and [datetime]::TryParse($raw, [ref]$parsed)) { return $parsed }
        }
    } catch {}
    # First paint this cycle: seed marker from this splash session.
    try {
        $seed = if ($script:startTime) { $script:startTime } else { Get-Date }
        if (-not (Test-Path -LiteralPath $marker)) {
            Set-Content -LiteralPath $marker -Value $seed.ToUniversalTime().ToString('o') -Encoding ASCII -ErrorAction SilentlyContinue
        }
        return $seed
    } catch {}
    return $(if ($script:startTime) { $script:startTime } else { Get-Date })
}

function Set-FbSplashTotalElapsedDisplay {
    param([TimeSpan]$Elapsed)
    if (-not $totalElapsedText) { return }
    if ($script:FbTotalElapsedFrozen -and $null -ne $script:FbTotalElapsedFrozenValue) {
        $totalElapsedText.Text = Format-FbSplashDuration -Elapsed $script:FbTotalElapsedFrozenValue
        return
    }
    $totalElapsedText.Text = Format-FbSplashDuration -Elapsed $Elapsed
}

function Update-FbSplashTotalElapsed {
    param([switch]$Freeze)
    try {
        if ($script:FbTotalElapsedFrozen -and -not $Freeze) {
            Set-FbSplashTotalElapsedDisplay -Elapsed $script:FbTotalElapsedFrozenValue
            return
        }
        $start = Get-FbSplashPipelineStartTime
        $span = (Get-Date) - $start
        if ($span.TotalSeconds -lt 0) { $span = [TimeSpan]::Zero }
        if ($Freeze) {
            $script:FbTotalElapsedFrozen = $true
            $script:FbTotalElapsedFrozenValue = $span
        }
        Set-FbSplashTotalElapsedDisplay -Elapsed $span
    } catch {
        Set-FbSplashTotalElapsedDisplay -Elapsed ([TimeSpan]::Zero)
    }
}

function Get-FbSplashRebootCount {
    # 5.4.21: REBOOTS is RebootIterations (reboots this loop issued).
    # BootCount-1 is fallback only when RI is still 0 (pre-5.4.21 state).
    $fromRi = 0
    $fromBoot = 0
    try {
        $statePath = Join-Path $FbRoot 'wu-state.json'
        if (Test-Path -LiteralPath $statePath) {
            $diskState = Get-Content -LiteralPath $statePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
            if ($diskState.PSObject.Properties.Name -contains 'RebootIterations') {
                try { $fromRi = [math]::Max(0, [int]$diskState.RebootIterations) } catch { $fromRi = 0 }
            }
            if ($diskState.PSObject.Properties.Name -contains 'BootCount') {
                try {
                    $bc = [int]$diskState.BootCount
                    if ($bc -gt 1) { $fromBoot = $bc - 1 }
                } catch { $fromBoot = 0 }
            }
        }
    } catch {}
    return $(if ($fromRi -gt 0) { $fromRi } else { $fromBoot })
}

function Set-FbSplashRebootDisplay {
    param([int]$Count = -1)
    if (-not $rebootCountText) { return }
    $n = if ($Count -ge 0) { $Count } else { Get-FbSplashRebootCount }
    $rebootCountText.Text = [string]$n
    # Screenshot: light-blue REBOOTS label + magenta count; blue pill border stays.
    $countAccent = if ($n -gt 0) { '#FFFF80AB' } else { '#FFB0C4DE' }
    $labelAccent = '#FF81D4FA'
    $borderAccent = '#FF4FC3F7'
    try {
        $conv = [System.Windows.Media.BrushConverter]::new()
        $rebootCountText.Foreground = $conv.ConvertFromString($countAccent)
        if ($rebootCountLabel) { $rebootCountLabel.Foreground = $conv.ConvertFromString($labelAccent) }
        if ($rebootCountHost) { $rebootCountHost.BorderBrush = $conv.ConvertFromString($borderAccent) }
    } catch {}
}

# DEV pill: resolved by the shared FirstBaseBuildIdentity.ps1 so this matches
# the WinPE banner and deploy screen exactly. It deliberately does NOT consult
# $FirstBaseBuildStatus - that is a checked-in constant, so honoring it made
# every release build show a DEV pill. Only per-build artifacts count:
# LW_VERSION.json (devBuild) and the .dev-build marker, both staged next to
# this script by TechInstall. No signal means release.
try {
    $fbIdentity = $null
    $fbIdentityPs1 = Join-Path $PSScriptRoot 'FirstBaseBuildIdentity.ps1'
    if (Test-Path -LiteralPath $fbIdentityPs1) {
        . $fbIdentityPs1
        $fbIdentity = Get-FbBuildIdentityForScript -ScriptRoot $PSScriptRoot -Layout Payload
    }
    if ($fbIdentity -and $fbIdentity.Dev -and $devBuildIndicator) {
        $devBuildIndicator.Visibility = [System.Windows.Visibility]::Visible
        if ($devBuildIndicatorText) {
            $devBuildIndicatorText.Text = 'DEV'
        }
    }
} catch {}

$logoBrush = $window.FindName('LogoBrush')
try {
    $logoLoaded = $false
    if ($logoBrush -and $script:FbSplashLogoB64) {
        $logoBytes = [Convert]::FromBase64String($script:FbSplashLogoB64)
        $logoMs = New-Object System.IO.MemoryStream(,$logoBytes)
        $bmpImg = New-Object System.Windows.Media.Imaging.BitmapImage
        $bmpImg.BeginInit(); $bmpImg.CacheOption='OnLoad'; $bmpImg.StreamSource=$logoMs; $bmpImg.EndInit(); $bmpImg.Freeze()
        $logoBrush.ImageSource = $bmpImg
        $logoLoaded = $true
    }
    if (-not $logoLoaded -and $logoBrush) {
        $icoCands = New-Object System.Collections.Generic.List[string]
        if ($PSScriptRoot) {
            [void]$icoCands.Add((Join-Path $PSScriptRoot 'FirstBase.ico'))
            try {
                $parent = Split-Path -Path $PSScriptRoot -Parent
                if ($parent) { [void]$icoCands.Add((Join-Path $parent 'FirstBase.ico')) }
            } catch {}
        }
        [void]$icoCands.Add('C:\Windows\Setup\FirstBase\FirstBase.ico')
        foreach ($ic in $icoCands) {
            if (-not $ic -or -not (Test-Path -LiteralPath $ic)) { continue }
            $bmpImg = New-Object System.Windows.Media.Imaging.BitmapImage
            $bmpImg.BeginInit()
            $bmpImg.CacheOption = 'OnLoad'
            $bmpImg.UriSource = New-Object System.Uri(('file:///' + $ic.Replace('\','/')))
            $bmpImg.EndInit()
            $bmpImg.Freeze()
            $logoBrush.ImageSource = $bmpImg
            $logoLoaded = $true
            break
        }
    }
} catch { try { Write-SplashLog ("logo load failed: {0}" -f $_.Exception.Message) 'WARN' } catch {} }

# Logo is the technician radial (fb-im / Restart / UEFI / Close). Wired after XAML load.
function Find-FbSplashFbImLauncher {
    if (Get-Command Find-FbSplashFbImScript -ErrorAction SilentlyContinue) {
        return (Find-FbSplashFbImScript)
    }
    $cands = New-Object System.Collections.Generic.List[string]
    if ($PSScriptRoot) {
        [void]$cands.Add((Join-Path $PSScriptRoot 'Tools\fb-im.ps1'))
        [void]$cands.Add((Join-Path $PSScriptRoot 'fb-im.ps1'))
        try {
            $parent = Split-Path -Path $PSScriptRoot -Parent
            if ($parent) {
                [void]$cands.Add((Join-Path $parent 'Tools\fb-im.ps1'))
                [void]$cands.Add((Join-Path $parent 'WUPayload\Tools\fb-im.ps1'))
            }
        } catch {}
    }
    [void]$cands.Add('C:\Windows\Setup\FirstBase\Tools\fb-im.ps1')
    [void]$cands.Add('C:\Windows\Setup\FirstBase\WUPayload\Tools\fb-im.ps1')
    try {
        Get-Volume -ErrorAction SilentlyContinue | ForEach-Object {
            if (-not $_.DriveLetter) { return }
            $root = ('{0}:\' -f $_.DriveLetter)
            [void]$cands.Add((Join-Path $root 'fb-im.cmd'))
            [void]$cands.Add((Join-Path $root 'FirstBase\WUPayload\Tools\fb-im.ps1'))
            [void]$cands.Add((Join-Path $root 'WUPayload\Tools\fb-im.ps1'))
        }
    } catch {}
    foreach ($c in $cands) {
        if ($c -and (Test-Path -LiteralPath $c)) { return $c }
    }
    return $null
}

