        ) -ErrorAction Stop | Out-Null
        Set-FbSplashTechStatus 'fb-im launched.' '#FF66BB6A'
    } catch {
        try { Write-SplashLog ("tech tools: fb-im launch failed: {0}" -f $_.Exception.Message) 'WARN' } catch {}
        Set-FbSplashTechStatus 'Could not launch fb-im.' '#FFEF5350'
    }
}

function Update-FbSplashRebootCountForManualRestart {
    # Tech-tools "Restart now" must bump the same governance counter the loop
    # bumps before patient reboot (RebootIterations), so the splash REBOOTS
    # pill reflects operator-issued restarts too. Creates a minimal state file
    # when the loop has not written one yet (e.g. SD00HN3R-1146).
    $riBump = 0
    $statePath = Join-Path $FbRoot 'wu-state.json'
    try {
        if (Test-Path -LiteralPath $statePath) {
            $riObj = Get-Content -LiteralPath $statePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
            if ($riObj.PSObject.Properties.Name -contains 'RebootIterations') {
                try { $riBump = [math]::Max(0, [int]$riObj.RebootIterations) } catch { $riBump = 0 }
            }
            $riBump++
            $riObj | Add-Member -NotePropertyName RebootIterations -NotePropertyValue $riBump -Force
            if (-not ($riObj.PSObject.Properties.Name -contains 'StartTime') -or -not $riObj.StartTime) {
                $riObj | Add-Member -NotePropertyName StartTime -NotePropertyValue ((Get-Date).ToString('o')) -Force
            }
            $riObj | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $statePath -Encoding UTF8 -Force
        } else {
            $riBump = 1
            try {
                if (-not (Test-Path -LiteralPath $FbRoot)) {
                    New-Item -ItemType Directory -Path $FbRoot -Force -ErrorAction SilentlyContinue | Out-Null
                }
            } catch {}
            $fresh = [ordered]@{
                RebootIterations = $riBump
                BootCount        = 0
                StartTime        = (Get-Date).ToString('o')
                LastPass         = 'splash-manual-restart'
            }
            ($fresh | ConvertTo-Json -Depth 4) | Set-Content -LiteralPath $statePath -Encoding UTF8 -Force
        }
        try { Write-SplashLog ("tech tools: RebootIterations bumped to {0} before manual restart" -f $riBump) 'INFO' } catch {}
        try { Set-FbSplashRebootDisplay -Count $riBump } catch {}
        return $riBump
    } catch {
        try { Write-SplashLog ("tech tools: RebootIterations bump failed: {0}" -f $_.Exception.Message) 'WARN' } catch {}
        return -1
    }
}

function Start-FbSplashImmediateRestart {
    try {
        Write-SplashLog 'tech tools: immediate restart requested (shutdown /r /f /t 0)' 'INFO'
        Set-FbSplashTechStatus 'Restarting now...' '#FFEF5350'
        try { [void](Update-FbSplashRebootCountForManualRestart) } catch {}
        $shutdown = Join-Path $env:SystemRoot 'System32\shutdown.exe'
        if (-not (Test-Path -LiteralPath $shutdown)) { $shutdown = 'shutdown.exe' }
        Start-Process -FilePath $shutdown -ArgumentList @('/r', '/f', '/t', '0') -WindowStyle Hidden -ErrorAction Stop | Out-Null
    } catch {
        try { Write-SplashLog ("tech tools: restart failed: {0}" -f $_.Exception.Message) 'WARN' } catch {}
        Set-FbSplashTechStatus 'Restart failed. Try again or use shutdown manually.' '#FFEF5350'
        try { Restart-Computer -Force -ErrorAction SilentlyContinue } catch {}
    }
}

