# Elapsed timer: must be $script:startTime (not $startTime) so DispatcherTimer ticks
# resolve the same field in this script scope (dot-sourced or -File).
# ELAPSED = this splash session (resets after restart). TOTAL ELAPSED = pipeline
# StartTime from wu-state (survives reboot) and freezes at OOBE handoff.
$script:startTime = Get-Date
$script:FbTotalElapsedFrozen = $false
$script:FbTotalElapsedFrozenValue = $null

# 2213z: native HWND for SetWindowPos(HWND_TOPMOST)  -  WPF Topmost is insufficient vs OOBE.
$script:SplashNativeHwnd = [IntPtr]::Zero
$script:SplashForegroundBoostDone = $false

# 2213u: when true, tech pressed F12 to turn Topmost off  -  do not fight them
# in the periodic refresh timer. Declared before SourceInitialized so the
# early native topmost path never reads an uninitialized variable.
$script:UserPreferredTopmostOff = $false

function Get-FbSplashOobe2214dCollectOobePidsForEnum {
    $pids = New-Object 'System.Collections.Generic.List[uint32]'
    foreach ($procBase in @('oobeldr', 'UserOOBEBroker', 'CloudExperienceHost', 'ShellExperienceHost', 'ApplicationFrameHost', 'WWAHost', 'oobe')) {
        Get-Process -Name $procBase -ErrorAction SilentlyContinue | ForEach-Object {
            try { [void]$pids.Add([uint32]$_.Id) } catch {}
        }
    }
    # PS may unwrap a single-element List when returned bare; always wrap in a property bag (fb-dump-final-1434).
    return [pscustomobject]@{ PidList = $pids }
}

function Get-FbSplashOobe2214dTickDiag {
    $hwSplash = $script:SplashNativeHwnd
    $oobePidCount = 0
    $enumHitCount = 0
    $pkg = Get-FbSplashOobe2214dCollectOobePidsForEnum
    $pids = $pkg.PidList
    $oobePidCount = $pids.Count
    if ($hwSplash -ne [IntPtr]::Zero -and $oobePidCount -gt 0) {
        try {
            $null = [FbSplashWin32Z]
            [FbSplashWin32Z]::Oobe2214cSetPids($pids.ToArray())
            $hits = [FbSplashWin32Z]::Oobe2214cCollectVisibleTopLevel($hwSplash)
            if ($null -ne $hits) {
                if ($hits -is [System.Array]) {
                    $enumHitCount = $hits.Length
                } else {
                    $enumHitCount = 1
                }
            }
        } catch {
            $enumHitCount = -1
        }
    }
    $fgLine = 'fg=(none)'
    try {
        $null = [FbSplashWin32Z]
        $fg = [FbSplashWin32Z]::GetForegroundWindow()
        if ($fg -ne [IntPtr]::Zero) {
            $pidFg = [uint32]0
            [void][FbSplashWin32Z]::GetWindowThreadProcessId($fg, [ref]$pidFg)
            $pn = 'unknown'
            try {
                $p = Get-Process -Id ([int]$pidFg) -ErrorAction SilentlyContinue
                if ($p) { $pn = $p.ProcessName + '.exe' }
            } catch { }
            $sb = New-Object System.Text.StringBuilder 256
            [void][FbSplashWin32Z]::GetClassName($fg, $sb, 256)
            $fgLine = ('fg={0} class={1} pid={2}' -f $pn, $sb.ToString(), $pidFg)
        }
    } catch {
        $fgLine = 'fg=(error)'
    }
    return [pscustomobject]@{
        OobePidCount = $oobePidCount
        EnumHitCount = $enumHitCount
        FgSummary    = $fgLine
    }
}

function Get-FbSplashOobe2214kFormatZAboveChain {
    param(
        [IntPtr]$StartHwnd,
        [int]$MaxDepth = 5
    )
    try {
        if ($StartHwnd -eq [IntPtr]::Zero) { return '(no-splash-hwnd)' }
        $null = [FbSplashWin32Z]
        $parts = New-Object System.Collections.Generic.List[string]
        $cur = $StartHwnd
        for ($i = 0; $i -lt $MaxDepth; $i++) {
            $nxt = [IntPtr]::Zero
            try { $nxt = [FbSplashWin32Z]::GetWindow($cur, [FbSplashWin32Z]::GW_HWNDPREV) } catch { break }
            if ($nxt -eq [IntPtr]::Zero) { break }
            if ($nxt -eq $cur) { break }
            $pidW = [uint32]0
            try { [void][FbSplashWin32Z]::GetWindowThreadProcessId($nxt, [ref]$pidW) } catch { $pidW = 0 }
            $pn = '?'
            try {
                $pp = Get-Process -Id ([int]$pidW) -ErrorAction SilentlyContinue
                if ($pp) { $pn = $pp.ProcessName }
            } catch { }
            $sb = New-Object System.Text.StringBuilder 96
            try { [void][FbSplashWin32Z]::GetClassName($nxt, $sb, 96) } catch { }
            $cls = ($sb.ToString() -replace '\s+', '.')
            if ($cls.Length -gt 28) { $cls = $cls.Substring(0, 28) }
            $parts.Add(('h{0:X}:p{1}:{2}:{3}' -f $nxt.ToInt64(), $pidW, $cls, $pn))
            $cur = $nxt
        }
        if ($parts.Count -eq 0) { return '(no-z-up-from-splash)' }
        return [string]::Join('|', [string[]]$parts.ToArray())
    } catch {
        return '(z-chain-error)'
    }
}

function Get-FbSplashOobe2214kBuildExtraDiagLine {
    try {
        $null = [FbSplashWin32Z]
        $hw = $script:SplashNativeHwnd
        $sb = New-Object System.Text.StringBuilder 512
        [void]$sb.Append(('wpfTop={0} wpfAct={1}' -f $window.Topmost, $window.IsActive))
        if ($hw -ne [IntPtr]::Zero) {
            try {
                $ex = [FbSplashWin32Z]::GetWindowLongPtr($hw, [FbSplashWin32Z]::GWL_EXSTYLE).ToInt64()
                $vis = [FbSplashWin32Z]::IsWindowVisible($hw)
                $ico = [FbSplashWin32Z]::IsIconic($hw)
                [void]$sb.Append((' splashEx=0x{0:X} splashVis={1} splashIconic={2}' -f $ex, $vis, $ico))
            } catch {
                [void]$sb.Append(' splashEx=(err)')
            }
        } else {
            [void]$sb.Append(' splashHwnd=0')
        }
        $fg = [FbSplashWin32Z]::GetForegroundWindow()
        $fgEq = ($fg -ne [IntPtr]::Zero -and $fg -eq $hw)
        [void]$sb.Append((' fgEqSplash={0}' -f $fgEq))
        if ($fg -ne [IntPtr]::Zero -and $fg -ne $hw) {
            $root = [FbSplashWin32Z]::GetAncestor($fg, [FbSplashWin32Z]::GA_ROOT)
            if ($root -eq [IntPtr]::Zero) { $root = $fg }
            $pidR = [uint32]0
            [void][FbSplashWin32Z]::GetWindowThreadProcessId($root, [ref]$pidR)
            $pnR = '?'
            try {
                $pr = Get-Process -Id ([int]$pidR) -ErrorAction SilentlyContinue
                if ($pr) { $pnR = $pr.ProcessName }
            } catch { }
            $vr = $false
            $ir = $false
            try { $vr = [FbSplashWin32Z]::IsWindowVisible($root) } catch { }
            try { $ir = [FbSplashWin32Z]::IsIconic($root) } catch { }
            [void]$sb.Append((' fgRoot=h{0:X} pid={1} proc={2} rootVis={3} rootIconic={4}' -f $root.ToInt64(), $pidR, $pnR, $vr, $ir))
        }
        $z = Get-FbSplashOobe2214kFormatZAboveChain -StartHwnd $hw -MaxDepth 5
        [void]$sb.Append(' zUp=')
        [void]$sb.Append($z)
        $line = $sb.ToString()
        if ($line.Length -gt 900) {
            return $line.Substring(0, 897) + '...'
        }
        return $line
    } catch {
        return ''
    }
}

function Invoke-FbSplashOobe2214dMaybeWriteTickDiag {
