    }
}

function Invoke-FbSplashOobe2214eMinimizeForegroundOobeRoot {
    try {
        if (-not (Test-FbSplashOobeHideAllowed)) { return }
        if ($script:UserPreferredTopmostOff) { return }
        $hwSplash = $script:SplashNativeHwnd
        if ($hwSplash -eq [IntPtr]::Zero) { return }
        try { $null = [FbSplashWin32Z] } catch { return }
        $fg = [FbSplashWin32Z]::GetForegroundWindow()
        if ($fg -eq [IntPtr]::Zero -or $fg -eq $hwSplash) { return }
        $root = [FbSplashWin32Z]::GetAncestor($fg, [FbSplashWin32Z]::GA_ROOT)
        if ($root -eq [IntPtr]::Zero) { $root = $fg }
        if ($root -eq $hwSplash) { return }
        if (Test-FbSplashSkipOobeHideHwnd -Hwnd $root) { return }
        $pidRoot = [uint32]0
        [void][FbSplashWin32Z]::GetWindowThreadProcessId($root, [ref]$pidRoot)
        if ($pidRoot -eq 0) { return }
        $procName = ''
        try {
            $p = Get-Process -Id ([int]$pidRoot) -ErrorAction SilentlyContinue
            if ($p) { $procName = $p.ProcessName }
        } catch { }
        if ([string]::IsNullOrWhiteSpace($procName)) { return }
        Invoke-FbSplashHideOobeHwndIfAllowed -Hwnd $root -ProcName $procName -Reason 'fg-oobe-root'
    } catch {
        try { Write-SplashLog ("2214f: OOBE-hide-fg-root EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch { }
    }
}

function Invoke-FbSplashApplyWin32ZOrder {
    param([Parameter(Mandatory = $true)][bool]$WantTopmost)
    try {
        $hw = $script:SplashNativeHwnd
        if ($hw -eq [IntPtr]::Zero) { return }
        try { $null = [FbSplashWin32Z] } catch { return }
        $after = if ($WantTopmost) { [FbSplashWin32Z]::HWND_TOPMOST } else { [FbSplashWin32Z]::HWND_NOTOPMOST }
        $flags = [FbSplashWin32Z]::SWP_NOMOVE -bor [FbSplashWin32Z]::SWP_NOSIZE -bor [FbSplashWin32Z]::SWP_NOACTIVATE -bor [FbSplashWin32Z]::SWP_SHOWWINDOW
        [void][FbSplashWin32Z]::FbSetLastError(0)
        $swpOk = [FbSplashWin32Z]::SetWindowPos($hw, $after, 0, 0, 0, 0, $flags)
        if (-not $swpOk) {
            $gleZ = 0
            try { $gleZ = [uint32][System.Runtime.InteropServices.Marshal]::GetLastWin32Error() } catch { }
            try { Write-SplashLog ("2213z: SetWindowPos(splash topmost refresh) returned false; gle={0}" -f $gleZ) 'WARN' } catch { }
        }
        # 2214a: WS_EX_TOPMOST reinforces native stacking vs OOBE (2213z HWND_TOPMOST alone still lost on fb-dump-final-1218).
        try {
            $cur = [FbSplashWin32Z]::GetWindowLongPtr($hw, [FbSplashWin32Z]::GWL_EXSTYLE).ToInt64()
            if ($WantTopmost) {
                $newLong = $cur -bor [FbSplashWin32Z]::WS_EX_TOPMOST
            } else {
                $newLong = $cur -band (-bnot [FbSplashWin32Z]::WS_EX_TOPMOST)
            }
            [void][FbSplashWin32Z]::SetWindowLongPtr($hw, [FbSplashWin32Z]::GWL_EXSTYLE, [IntPtr]::new($newLong))
        } catch { }
    } catch { }
}

function Invoke-FbSplashOobe2214lMaybeDiagFgMismatch {
    # 2214l-skip-fg-mismatch: throttled 3s. Fires when the fg-gated pass-1 would skip because the
    # foreground window is NOT a WWAHost CoreWindow, but visible WWAHost roots actually exist.
    # Confirms the "OOBE paints above while not fg" hypothesis on field dumps.
    try {
        $now = [DateTimeOffset]::UtcNow
        if ($null -ne $script:Fb2214lFgMismatchLastLogUtc) {
            if (($now - $script:Fb2214lFgMismatchLastLogUtc).TotalSeconds -lt 3) { return }
        }
        try { $null = [FbSplashWin32Z] } catch { return }
        $hwSplash = $script:SplashNativeHwnd
        if ($hwSplash -eq [IntPtr]::Zero) { return }
        $wwahostPids = New-Object 'System.Collections.Generic.List[uint32]'
        Get-Process -Name 'WWAHost' -ErrorAction SilentlyContinue | ForEach-Object {
            try { [void]$wwahostPids.Add([uint32]$_.Id) } catch {}
        }
        if ($wwahostPids.Count -eq 0) { return }
        [FbSplashWin32Z]::Oobe2214cSetPids($wwahostPids.ToArray())
        $hits = [FbSplashWin32Z]::Oobe2214cCollectVisibleTopLevel($hwSplash)
        if ($null -eq $hits -or $hits.Length -eq 0) { return }
        $fg = [FbSplashWin32Z]::GetForegroundWindow()
        $fgCls = ''
        $fgProc = ''
        if ($fg -ne [IntPtr]::Zero) {
            $sbCls = New-Object System.Text.StringBuilder 256
            [void][FbSplashWin32Z]::GetClassName($fg, $sbCls, 256)
            $fgCls = $sbCls.ToString()
            $pidFg = [uint32]0
            [void][FbSplashWin32Z]::GetWindowThreadProcessId($fg, [ref]$pidFg)
            try {
                $p = Get-Process -Id ([int]$pidFg) -ErrorAction SilentlyContinue
                if ($p) { $fgProc = $p.ProcessName + '.exe' }
            } catch {}
        }
        $script:Fb2214lFgMismatchLastLogUtc = $now
        Write-SplashLog ("2214l-skip-fg-mismatch: {0} visible WWAHost root(s) present; fg=0x{1:X} proc={2} class={3}; pass-1 fg-gate skipping but enum pass active" -f $hits.Length, $fg.ToInt64(), $fgProc, $fgCls)
    } catch {}
}

function Invoke-FbSplashOobe2214lEnumerateAndPlaceAllWwahostBehindSplash {
    <#
      2214l-enum: Enumerate ALL visible top-level WWAHost HWNDs (no fg-window gate) and call
      SetWindowPos(hwndOobe, hwndInsertAfter=splash, ...) on each. Complements pass-1/pass-2 of
      Invoke-FbSplashOobe2214lPlaceWwahostRootBehindSplash which only fires when the fg is a CoreWindow.
      Gates: marker absent (or 2222 handoff active). Runs in Audit too so WWAHost
      stacks behind splash without SW_MINIMIZE (minimize stays overlay-gated in 2214e/2214c).
      Throttle: 1.5s via $script:Fb2214lEnumLastRun. Pass -NoThrottle for the early Z-pass at Loaded/SourceInitialized.
    #>
    param([switch]$NoThrottle)
    try {
        if (-not $NoThrottle) {
            $now = [DateTimeOffset]::UtcNow
            if ($null -ne $script:Fb2214lEnumLastRun) {
                if (($now - $script:Fb2214lEnumLastRun).TotalSeconds -lt 1.5) { return }
            }
            $script:Fb2214lEnumLastRun = $now
        }
        if ((Test-Path -LiteralPath $Marker) -and -not (Test-FbSplash2222OobeOverlayHandoffActive)) { return }
        if ($script:UserPreferredTopmostOff) { return }
        $hwSplash = $script:SplashNativeHwnd
        if ($hwSplash -eq [IntPtr]::Zero) { return }
        try { $null = [FbSplashWin32Z] } catch { return }
        if (-not [FbSplashWin32Z]::IsWindow($hwSplash)) { return }
        $wwahostPids = New-Object 'System.Collections.Generic.List[uint32]'
        Get-Process -Name 'WWAHost' -ErrorAction SilentlyContinue | ForEach-Object {
            try { [void]$wwahostPids.Add([uint32]$_.Id) } catch {}
        }
        if ($wwahostPids.Count -eq 0) { return }
        [FbSplashWin32Z]::Oobe2214cSetPids($wwahostPids.ToArray())
        $hits = [FbSplashWin32Z]::Oobe2214cCollectVisibleTopLevel($hwSplash)
        if ($null -eq $hits -or $hits.Length -eq 0) { return }
        $swpFlags = [FbSplashWin32Z]::SWP_NOMOVE -bor [FbSplashWin32Z]::SWP_NOSIZE -bor [FbSplashWin32Z]::SWP_NOACTIVATE
        foreach ($h in @($hits)) {
            if ($h -eq [IntPtr]::Zero) { continue }
            if (-not [FbSplashWin32Z]::IsWindow($h)) { continue }
            $gle = [uint32]0
            $ok = [FbSplashWin32Z]::Oobe2214mSetWindowPosZBehindSplash($h, $hwSplash, $swpFlags, [ref]$gle)
            Write-SplashLog ("2214l-enum: SetWindowPos OOBE-root below splash hwndOobe={0} hwndSplash={1} ok={2} gle={3} noThrottle={4}" -f $h, $hwSplash, $ok, $gle, $NoThrottle.IsPresent)
        }
    } catch {
        try { Write-SplashLog ("2214l-enum: enumerate EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch {}
    }
}

function Invoke-FbSplashOobe2214lPlaceWwahostRootBehindSplash {
    <#
      2214l (+ 2214m hardened): WWAHost OOBE (2214j SW_MINIMIZE skip family) can still stack above the splash.
      After Invoke-FbSplashApplyWin32ZOrder(HWND_TOPMOST) on the splash, call
      SetWindowPos(ooobeRootHwnd, splashHwnd, 0,0,0,0, SWP_NOMOVE|SWP_NOSIZE|SWP_NOACTIVATE)
      so the OOBE root is Z-ordered immediately *below* the splash (hwndInsertAfter per MSDN).
      Do not set SWP_NOZORDER. Throttled **4s** per GA_ROOT HWND for **pass=1** only; **pass=2** (same tick,
      after 2214b reclaim) has no extra throttle  -  shell may re-order Z after AttachThreadInput / SetForegroundWindow.
      Logs ``gle=`` (last Win32 error; cleared before SetWindowPos). No SW_FORCEMINIMIZE / HWND_NOTOPMOST on OOBE (2214h).
      Gate unchanged: **WWAHost.exe** + foreground class contains **CoreWindow** only (do not broaden without risk note).
      **2222:** When the updates-done marker exists but **FirstBase-Splash-Oobe-Overlay.mode** is also present (2221 handoff),
      this function **does not** early-return on marker alone  -  Z-order stomp must keep OOBE below the splash until scrub.
    #>
    param(
        [Parameter()][ValidateSet(1, 2)]
        [int]$RestackPass = 1
    )
    try {
        if ($RestackPass -eq 2) {
            if (-not $script:Oobe2214mDid2214lPass1ZStompThisTick) { return }
        }
        if ((Test-Path -LiteralPath $Marker) -and -not (Test-FbSplash2222OobeOverlayHandoffActive)) { return }
        if ($script:UserPreferredTopmostOff) { return }
        $hwSplash = $script:SplashNativeHwnd
        if ($hwSplash -eq [IntPtr]::Zero) { return }
        try { $null = [FbSplashWin32Z] } catch { return }
        if (-not [FbSplashWin32Z]::IsWindow($hwSplash)) { return }
        $fg = [FbSplashWin32Z]::GetForegroundWindow()
        if ($fg -eq [IntPtr]::Zero -or $fg -eq $hwSplash) { return }
        if (-not [FbSplashWin32Z]::IsWindow($fg)) { return }
        $sbCls = New-Object System.Text.StringBuilder 256
        [void][FbSplashWin32Z]::GetClassName($fg, $sbCls, 256)
        $clsFg = $sbCls.ToString()
        if ([string]::IsNullOrWhiteSpace($clsFg)) { return }
        if ($clsFg.IndexOf('CoreWindow', [System.StringComparison]::OrdinalIgnoreCase) -lt 0) {
            if ($RestackPass -eq 1) { Invoke-FbSplashOobe2214lMaybeDiagFgMismatch }
            return
        }
        $root = [FbSplashWin32Z]::GetAncestor($fg, [FbSplashWin32Z]::GA_ROOT)
        if ($root -eq [IntPtr]::Zero) { $root = $fg }
        if ($root -eq [IntPtr]::Zero -or $root -eq $hwSplash) { return }
        if (-not [FbSplashWin32Z]::IsWindow($root)) { return }
        $pidRoot = [uint32]0
        [void][FbSplashWin32Z]::GetWindowThreadProcessId($root, [ref]$pidRoot)
        if ($pidRoot -eq 0) { return }
        $procName = ''
        try {
            $p = Get-Process -Id ([int]$pidRoot) -ErrorAction SilentlyContinue
            if ($p) { $procName = $p.ProcessName }
        } catch { }
        $pnLower = if ($procName) { ($procName + '.exe').ToLowerInvariant() } else { '' }
        if ($pnLower -ne 'wwahost.exe') {
            if ($RestackPass -eq 1) { Invoke-FbSplashOobe2214lMaybeDiagFgMismatch }
            return
        }
        $throttleKey = $root.ToInt64().ToString()
        $now = [DateTimeOffset]::UtcNow
        if ($RestackPass -eq 1) {
            if ($null -ne $script:Oobe2214lZBehindSplashLastUtcByRoot -and $script:Oobe2214lZBehindSplashLastUtcByRoot.ContainsKey($throttleKey)) {
                $last = $script:Oobe2214lZBehindSplashLastUtcByRoot[$throttleKey]
                if (($now - $last).TotalSeconds -lt 4) { return }
            }
        }
        $swpFlags = [FbSplashWin32Z]::SWP_NOMOVE -bor [FbSplashWin32Z]::SWP_NOSIZE -bor [FbSplashWin32Z]::SWP_NOACTIVATE
        $gle = [uint32]0
        $ok = [FbSplashWin32Z]::Oobe2214mSetWindowPosZBehindSplash($root, $hwSplash, $swpFlags, [ref]$gle)
        if ($RestackPass -eq 1) {
            try { $script:Oobe2214lZBehindSplashLastUtcByRoot[$throttleKey] = $now } catch { }
            $script:Oobe2214mDid2214lPass1ZStompThisTick = $true
        }
        Write-SplashLog ("2214l: OOBE-Z-behind-splash hwndOobe={0} hwndSplash={1} fgClass={2} SetWindowPos={3} gle={4} pass={5}" -f $root, $hwSplash, $clsFg, $ok, $gle, $RestackPass)
    } catch {
        try { Write-SplashLog ("2214l: OOBE-Z-behind-splash EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch { }
    }
}

function Invoke-FbSplashSynthesizeInputNudge {
    # 2303: Fire a real Alt (VK_MENU) key down+up immediately before SetForegroundWindow so Windows treats the reclaim
    # as input-driven and grants the foreground change - this is the SAME activation provenance the operator's working
    # Alt+Tab uses. Replaces the earlier inert VK_F15 nudge (field bundle 1253 proved F15 did not confer activation
    # rights: SetForegroundWindow stayed False even with the foreground lock at 0). Alt is a benign no-op tap in OOBE
    # (no menu is opened by a down+up with no other key). Default ON; set env FIRSTBASE_SPLASH_DISABLE_SYNTH_INPUT=1 to
    # opt out. Wrapped so a native failure can never crash the splash.
    if ($env:FIRSTBASE_SPLASH_DISABLE_SYNTH_INPUT -eq '1') { return }
    try {
        try { $null = [FbSplashWin32Z] } catch { return }
        [FbSplashWin32Z]::keybd_event([FbSplashWin32Z]::VK_MENU, 0, 0, [System.UIntPtr]::Zero)
        [FbSplashWin32Z]::keybd_event([FbSplashWin32Z]::VK_MENU, 0, [FbSplashWin32Z]::KEYEVENTF_KEYUP, [System.UIntPtr]::Zero)
        Write-SplashLog '2303: synthetic VK_MENU (Alt) input nudge fired (grants user-input activation provenance for SetForegroundWindow; benign no-op tap in OOBE)'
    } catch {
        try { Write-SplashLog ("2303: synthetic input nudge EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch { }
    }
}

function Invoke-FbSplashForceSelfForeground {
    # 2303 Fix 1: force the SPLASH's OWN window to the foreground using only self-window + our-own-input operations
    # (seal-safe: never touches OOBE). Sequence: Alt-tap nudge -> AllowSetForegroundWindow -> SetWindowPos(HWND_TOPMOST)
    # -> BringWindowToTop -> SetForegroundWindow. If that still does not land, do ONE guarded minimize->restore of the
    # splash (restoring from minimized grants foreground-activation rights) then re-assert topmost + SetForegroundWindow.
    # Flicker guard: returns immediately if the splash is already foreground; the minimize->restore runs at most once
    # per call and only when the direct attempt failed. Fully wrapped so it can never throw out of a tick.
    param([string]$Reason = '')
    try {
        $hwSplash = $script:SplashNativeHwnd
        if ($null -eq $hwSplash -or $hwSplash -eq [IntPtr]::Zero) { return $false }
        try { $null = [FbSplashWin32Z] } catch { return $false }
        if ([FbSplashWin32Z]::GetForegroundWindow() -eq $hwSplash) { return $true }
        $swpFlags = [FbSplashWin32Z]::SWP_NOMOVE -bor [FbSplashWin32Z]::SWP_NOSIZE -bor [FbSplashWin32Z]::SWP_NOACTIVATE
        Invoke-FbSplashSynthesizeInputNudge
        [void][FbSplashWin32Z]::AllowSetForegroundWindow([uint32]::MaxValue)
        [void][FbSplashWin32Z]::SetWindowPos($hwSplash, [FbSplashWin32Z]::HWND_TOPMOST, 0, 0, 0, 0, $swpFlags)
        [void][FbSplashWin32Z]::BringWindowToTop($hwSplash)
        $sfw = [FbSplashWin32Z]::SetForegroundWindow($hwSplash)
        $gle = [Runtime.InteropServices.Marshal]::GetLastWin32Error()
        if ($sfw -and ([FbSplashWin32Z]::GetForegroundWindow() -eq $hwSplash)) {
            Write-SplashLog ("2303 self-activate: direct sfw=True gle={0} reason={1}" -f $gle, $Reason)
            return $true
        }
        # 2304: cheap first escalation - SwitchToThisWindow is the Alt+Tab switcher's own API and often confers the
        # activation SetForegroundWindow was denied (operator confirmed Alt+Tab surfaces the splash). Seal-safe: acts
        # only on the splash's own hwnd. Try it before the heavier minimize->restore flicker.
        [void][FbSplashWin32Z]::SwitchToThisWindow($hwSplash, $true)
        [void][FbSplashWin32Z]::SetForegroundWindow($hwSplash)
        if ([FbSplashWin32Z]::GetForegroundWindow() -eq $hwSplash) {
            Write-SplashLog ("2304 self-activate: switchToThisWindow fgEqSplash=True reason={0}" -f $Reason)
            return $true
        }
        # Direct attempt failed - one guarded minimize->restore, then re-assert.
        [void][FbSplashWin32Z]::ShowWindow($hwSplash, [FbSplashWin32Z]::SW_MINIMIZE)
        [void][FbSplashWin32Z]::ShowWindow($hwSplash, [FbSplashWin32Z]::SW_RESTORE)
        [void][FbSplashWin32Z]::SetWindowPos($hwSplash, [FbSplashWin32Z]::HWND_TOPMOST, 0, 0, 0, 0, $swpFlags)
        [void][FbSplashWin32Z]::BringWindowToTop($hwSplash)
        Invoke-FbSplashSynthesizeInputNudge
        $sfw2 = [FbSplashWin32Z]::SetForegroundWindow($hwSplash)
        $gle2 = [Runtime.InteropServices.Marshal]::GetLastWin32Error()
        # 2304: final self-window attempt - SwitchToThisWindow again after the restore (still seal-safe: own hwnd only).
        if (-not ([FbSplashWin32Z]::GetForegroundWindow() -eq $hwSplash)) {
            [void][FbSplashWin32Z]::SwitchToThisWindow($hwSplash, $true)
            [void][FbSplashWin32Z]::SetForegroundWindow($hwSplash)
        }
        $fgEq = ([FbSplashWin32Z]::GetForegroundWindow() -eq $hwSplash)
        Write-SplashLog ("2304 self-activate: minRestore+switch sfw={0} gle={1} fgEqSplash={2} reason={3}" -f $sfw2, $gle2, $fgEq, $Reason)
        return $fgEq
    } catch {
        try { Write-SplashLog ("2303 self-activate: EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch { }
        return $false
    }
}

function Invoke-FbSplashMaybeReclaimForegroundFromOobe {
    try {
        if ($script:UserPreferredTopmostOff) { return }
        try {
            if (Get-Command Test-FbSplashShouldYieldToOperator -ErrorAction SilentlyContinue) {
                if (Test-FbSplashShouldYieldToOperator) { return }
            }
        } catch {}
        $hwSplash = $script:SplashNativeHwnd
        if ($hwSplash -eq [IntPtr]::Zero) { return }
        try { $null = [FbSplashWin32Z] } catch { return }
        $fg = [FbSplashWin32Z]::GetForegroundWindow()
        if ($fg -eq [IntPtr]::Zero -or $fg -eq $hwSplash) { return }
        $pidFg = [uint32]0
        $fgThread = [FbSplashWin32Z]::GetWindowThreadProcessId($fg, [ref]$pidFg)
        if ($pidFg -eq 0) { return }
        $procName = ''
        try {
            $p = Get-Process -Id ([int]$pidFg) -ErrorAction SilentlyContinue
            if ($p) { $procName = $p.ProcessName }
        } catch { }
        $pn = if ($procName) { $procName + '.exe' } else { '' }
        $pnLower = $pn.ToLowerInvariant()
        $isOobeFg = ($pnLower -eq 'oobeldr.exe') -or ($pnLower -eq 'useroobebroker.exe') -or ($pnLower -eq 'cloudexperiencehost.exe') -or ($pnLower -eq 'shellexperiencehost.exe') -or ($pnLower -eq 'wwahost.exe')
        if ($pnLower -eq 'applicationframehost.exe') {
            $titleAfh = ''
            try { $titleAfh = Get-FbSplashWindowText -Hwnd $fg } catch {}
            $isOobeFg = $true
        }
        if (-not $isOobeFg) { return }
        $sb = New-Object System.Text.StringBuilder 256
        [void][FbSplashWin32Z]::GetClassName($fg, $sb, 256)
        $cls = $sb.ToString()
        $curThread = [FbSplashWin32Z]::GetCurrentThreadId()
        $didAttach = $false
        try {
            if ($fgThread -ne 0 -and $fgThread -ne $curThread) {
                $didAttach = [FbSplashWin32Z]::AttachThreadInput($fgThread, $curThread, $true)
            }
            [void][FbSplashWin32Z]::AllowSetForegroundWindow([uint32]::MaxValue)
            # 2296: synthetic input nudge on the gated OOBE reclaim path (fires only when we are actually reclaiming).
            Invoke-FbSplashSynthesizeInputNudge
            $sfwOk = [FbSplashWin32Z]::SetForegroundWindow($hwSplash)
            $sfwGle = [Runtime.InteropServices.Marshal]::GetLastWin32Error()
            [void][FbSplashWin32Z]::BringWindowToTop($hwSplash)
            Write-SplashLog ("2214b: AttachThreadInput-FG (attachTried={0}, attachOk={1}, SetForegroundWindow={2}, sfwGle={3}, fgThread={4}, curThread={5}, fgProc={6}, fgClass={7}, fgPid={8})" -f ($fgThread -ne $curThread), $didAttach, $sfwOk, $sfwGle, $fgThread, $curThread, $pn, $cls, $pidFg)
            Write-SplashLog ("2214a: OOBE-FG-reclaim (fgProc={0}, fgClass={1}, fgPid={2})" -f $pn, $cls, $pidFg)
            # 2303 Fix 1: if SetForegroundWindow was refused (activation-privilege rule, not the lock), escalate to the
            # self-window Alt-tap + minimize->restore activation (seal-safe; acts only on the splash's own hwnd/input).
            if (-not $sfwOk) {
                $forced = Invoke-FbSplashForceSelfForeground -Reason 'reclaim-2214b'
                # 2304: the self-window activation (SetForegroundWindow / SwitchToThisWindow / min-restore) still could not
                # take the foreground from the OOBE host. The ONLY primitive proven to work is killing the OOBE process
                # that holds the foreground - post-kill activate succeeds every time. Escalate to it here so the reclaim
                # path is coupled to the proven kill+activate instead of losing to the respawn. Seal-safe:
                # Invoke-FbSplashKillOobeForegroundHost self-gates on Test-FbSplashSealWindowActive and the Layer 2 toggle,
                # so this NEVER fires during the customer-OOBE seal window. Fully wrapped.
                if (-not $forced) {
                    try {
                        $cfgR = Get-FbSplashSuppressionConfig
                        if ($cfgR -and $cfgR.KillOobe) {
                            Write-SplashLog ("2304 escalate: self-reclaim failed; invoking seal-gated kill+activate (fgProc={0} fgPid={1})" -f $pn, $pidFg)
                            Invoke-FbSplashKillOobeForegroundHost -Enabled $true
                        }
                    } catch { try { Write-SplashLog ("2304 escalate: EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch { } }
                }
            }
        } catch {
            try {
                Write-SplashLog ("2214b: AttachThreadInput-FG EXCEPTION {0}" -f $_.Exception.Message) 'WARN'
            } catch { }
        } finally {
            if ($didAttach) {
                try { [void][FbSplashWin32Z]::AttachThreadInput($fgThread, $curThread, $false) } catch { }
            }
        }
    } catch { }
}

function Invoke-FbSplashOobe2214cResolveProcNameFromHwnd {
    param([IntPtr]$Hwnd)
    try {
        $pidU = [uint32]0
        [void][FbSplashWin32Z]::GetWindowThreadProcessId($Hwnd, [ref]$pidU)
        if ($pidU -eq 0) { return 'unknown' }
        $p = Get-Process -Id ([int]$pidU) -ErrorAction SilentlyContinue
        if ($p) { return ($p.ProcessName + '.exe') }
        return ('pid' + $pidU)
    } catch {
        return 'unknown'
    }
}

function Invoke-FbSplashOobe2214cRestoreAll {
    param([string]$Reason)
    try { $null = [FbSplashWin32Z] } catch { return }
    if ($null -eq $script:OobeMin2214cHidden -or $script:OobeMin2214cHidden.Count -eq 0) { return }
    foreach ($hwndStr in [string[]]@($script:OobeMin2214cHidden.Keys)) {
        $storedProc = ''
        try { $storedProc = [string]$script:OobeMin2214cHidden[$hwndStr] } catch { $storedProc = '' }
        $ptr = [IntPtr]::Zero
        try { $ptr = [IntPtr]::new([long]::Parse($hwndStr)) } catch { continue }
        if (-not [FbSplashWin32Z]::IsWindow($ptr)) {
            try { [void]$script:OobeMin2214cHidden.Remove($hwndStr) } catch {}
            continue
        }
        $liveProc = Invoke-FbSplashOobe2214cResolveProcNameFromHwnd -Hwnd $ptr
        $ok = [FbSplashWin32Z]::ShowWindow($ptr, [FbSplashWin32Z]::SW_SHOW)
        try { [void][FbSplashWin32Z]::ShowWindow($ptr, [FbSplashWin32Z]::SW_RESTORE) } catch {}
        Write-SplashLog ("2214c: OOBE-restore reason={0} hwnd={1} storedProc={2} liveProc={3} ShowWindow={4}" -f $Reason, $ptr, $storedProc, $liveProc, $ok)
        try { [void]$script:OobeMin2214cHidden.Remove($hwndStr) } catch {}
    }
}

function Invoke-FbSplashOobe2214cApplyMinimizeWhileUpdates {
    try {
        if ($script:UserPreferredTopmostOff) {
            Invoke-FbSplashOobe2214cRestoreAll -Reason 'f12-topmost-off'
            return
        }
        if (-not (Test-FbSplashOobeHideAllowed)) {
            if (-not $script:Fb2241SkipWwahostMinForThisTick) {
                Invoke-FbSplashOobe2214cRestoreAll -Reason 'hide-no-longer-allowed'
            }
            return
        }
        $hwSplash = $script:SplashNativeHwnd
        if ($hwSplash -eq [IntPtr]::Zero) { return }
        try { $null = [FbSplashWin32Z] } catch { return }

        $pkg = Get-FbSplashOobe2214dCollectOobePidsForEnum
        $pids = $pkg.PidList
        if ($pids.Count -gt 0) {
            [FbSplashWin32Z]::Oobe2214cSetPids($pids.ToArray())
            $hits = [FbSplashWin32Z]::Oobe2214cCollectVisibleTopLevel($hwSplash)
            foreach ($h in @($hits)) {
                if ($h -eq [IntPtr]::Zero) { continue }
                $pn = Invoke-FbSplashOobe2214cResolveProcNameFromHwnd -Hwnd $h
                Invoke-FbSplashHideOobeHwndIfAllowed -Hwnd $h -ProcName $pn -Reason 'while-updates'
            }
        }
        # 5.4.20: CXH error / language-region titles may not sit on the PID enum (new HWND after minutes).
        try {
            $chromeHits = [FbSplashWin32Z]::OobeChromeCollectVisibleTopLevel($hwSplash)
        } catch { $chromeHits = @() }
        foreach ($h in @($chromeHits)) {
            if ($h -eq [IntPtr]::Zero) { continue }
            $titleC = Get-FbSplashOobeHwndTitle -Hwnd $h
            if (-not (Test-FbSplashOobeChromeTitle -Title $titleC)) { continue }
            $pnC = Invoke-FbSplashOobe2214cResolveProcNameFromHwnd -Hwnd $h
            Invoke-FbSplashHideOobeHwndIfAllowed -Hwnd $h -ProcName $pnC -Reason 'cxh-chrome-title'
        }
    } catch {
        try { Write-SplashLog ("2214c: OOBE-hide-enum EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch {}
    }
}

function Invoke-FbSplashTryForegroundOnce {
    if ($script:SplashForegroundBoostDone) { return }
    try {
        $hw = $script:SplashNativeHwnd
        if ($hw -eq [IntPtr]::Zero) { return }
        try { $null = [FbSplashWin32Z] } catch { return }
        [void][FbSplashWin32Z]::AllowSetForegroundWindow([uint32]::MaxValue)
        # 2296: synthetic input nudge before the one-time SetForegroundWindow so it is honored under the OOBE foreground lock.
        Invoke-FbSplashSynthesizeInputNudge
        [void][FbSplashWin32Z]::SetForegroundWindow($hw)
        $script:SplashForegroundBoostDone = $true
        Write-SplashLog '2213z: one-time AllowSetForegroundWindow+SetForegroundWindow (OOBE visibility; may steal focus briefly)'
    } catch { }
}

