try {
    Write-SplashLog "Configuring SplashTopmostRefresh DispatcherTimer (2214m: 2214l Z-behind + gle + pass2 after 2214b + WWAHOST SetWindowPos + 2214j no SW_MIN + pre-topmost + 1.5s + 2214h + 2214f + 2214c + 2214b + 2213z)..."
    $script:SplashTopmostRefreshTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:SplashTopmostRefreshTimer.Interval = [TimeSpan]::FromSeconds(1.5)
    $script:SplashTopmostRefreshTimer.Add_Tick({
        try {
            $script:Oobe2214mDid2214lPass1ZStompThisTick = $false
            $script:Fb2241SkipWwahostMinForThisTick = $false
            if (-not $window.IsVisible) { return }
            try {
                if (Test-FbSplashNeedsCoverScreen -Window $window) {
                    Invoke-FbSplashCoverScreen -Window $window
                }
            } catch {}
            if ($window.WindowState -eq [System.Windows.WindowState]::Minimized) {
                try { Invoke-FbSplashOobe2214cRestoreAll -Reason 'splash-window-minimized' } catch {}
                return
            }
            # 2241: splash health check - if splash not confirmed visible after 30s, skip WWAHost
            # SW_MINIMIZE for this tick so the black screen persists as a fallback visual signal.
            # Z-order / topmost recovery still runs; only the WWAHost hide is deferred.
            if (-not $script:FbSplashConfirmedVisible) {
                try {
                    $elapsed2241 = ([System.DateTimeOffset]::UtcNow - $script:FbSplashStartUtc).TotalSeconds
                    if ($elapsed2241 -gt 30) {
                        Write-SplashLog 'splash-confirmed-not-visible: allowing black screen to persist as fallback visual; skipping WWAHost SW_MINIMIZE for this tick' 'WARN'
                        $script:Fb2241SkipWwahostMinForThisTick = $true
                    }
                } catch {}
            }
            Invoke-FbSplashOobe2214dMaybeWriteTickDiag
            # 2300 Phase 0 diagnostics (always on) + Layer 2 kill (gated by toggle + seal-window guard).
            Invoke-FbSplashSuppressionDiagnosticsAndKillTick
            $yield = $false
            try { $yield = [bool](Invoke-FbSplashHonorOperatorForeground) } catch { $yield = $false }
            if (-not $script:UserPreferredTopmostOff -and -not $yield) {
                $hwPre = $script:SplashNativeHwnd
                if ($hwPre -ne [IntPtr]::Zero) {
                    try {
                        $window.Topmost = $true
                        Invoke-FbSplashApplyWin32ZOrder -WantTopmost $true
                    } catch { }
                }
            }
            Invoke-FbSplashOobe2214eMinimizeForegroundOobeRoot
            Invoke-FbSplashOobe2214cApplyMinimizeWhileUpdates
            if ($script:UserPreferredTopmostOff) { return }
            if (-not $yield) {
                $window.Topmost = $true
                Invoke-FbSplashApplyWin32ZOrder -WantTopmost $true
            }
            # 2214l/2214m: OOBE Z-order hwndInsertAfter=splash  -  pass=1 after splash HWND_TOPMOST + WS_EX_TOPMOST, before Activate/reclaim.
            Invoke-FbSplashOobe2214lPlaceWwahostRootBehindSplash -RestackPass 1
            # Splash overtakes operator apps. $yield is always false unless F12/topmost-off.
            if ($yield) {
                try { Invoke-FbSplashHonorOperatorForeground | Out-Null } catch {}
            } else {
                [void]$window.Activate()
                Invoke-FbSplashMaybeReclaimForegroundFromOobe
            }
            # 2214m: Second SetWindowPos same tick (no extra throttle)  -  shell may re-order Z after 2214b.
            Invoke-FbSplashOobe2214lPlaceWwahostRootBehindSplash -RestackPass 2
            # 2214l-enum: enumerate all visible WWAHost roots without fg gate (1.5s throttle).
            Invoke-FbSplashOobe2214lEnumerateAndPlaceAllWwahostBehindSplash
            if ($yield) {
                try { Invoke-FbSplashHonorOperatorForeground | Out-Null } catch {}
            }
        } catch {
            try {
                $msg = [string]$_.Exception.Message
                if ($script:SplashTopmostTickLastExMsg -ne $msg) {
                    $script:SplashTopmostTickLastExMsg = $msg
                    Write-SplashLog ("SplashTopmostRefresh tick EXCEPTION: {0}" -f $msg) 'WARN'
                }
            } catch { }
        }
    })
    Write-SplashLog "SplashTopmostRefresh DispatcherTimer configured"
} catch {
    Write-SplashLog "FAILED at SplashTopmostRefresh timer setup: $($_.Exception.GetType().FullName): $($_.Exception.Message)" 'WARN'
}

function Get-FbSplashShortStatusLine {
    param([string]$PhaseOrPass)
    $p = if ([string]::IsNullOrWhiteSpace($PhaseOrPass)) { '' } else { $PhaseOrPass.Trim() }
    if ($p.Length -eq 0 -or $p -eq 'Startup' -or $p -eq 'Preparing') { return 'Preparing your computer' }
    if ($p -eq 'Network') { return 'Waiting for network connection' }
    if ($p -eq 'Installing' -or $p -eq 'Install') { return 'Installing' }
    if ($p -eq 'Downloading' -or $p -eq 'Download') { return 'Downloading and installing updates' }
    if ($p -eq 'Completed') { return 'Completed' }
    if ($p -eq 'Scanning' -or $p -eq 'Checking') { return 'Checking for updates' }
    if ($p -eq 'Verifying' -or $p -eq 'FinalCheck') { return 'Verifying updates' }
    if ($p -eq 'ApplyingUpdates' -or $p -match '(?i)applying') { return 'Windows is applying updates - please wait' }
    if ($p -eq 'ManualRestart') { return 'Restart this PC - hold the power button if it will not restart' }
    if ($p -eq 'Rebooting' -or $p -match '(?i)^reboot') { return 'Restarting to continue updates' }
    if ($p -match '(?i)handoff|sysprep|oobe') { return 'Preparing OOBE handoff' }
    return 'Downloading and installing updates'
}

function Resolve-FbSplashDisplayPhase {
    # STATUS pill must follow the latest wu-status.json phase. Completed is never a
    # terminal latch: a later Downloading/Installing phase (or in-flight row) wins.
    param($State)
    if (-not $State) { return '' }
    $phase = [string]$State.Phase
    $updatedAt = [string]$State.UpdatedAt
    $inflight = $null
    foreach ($u in @($State.Updates)) {
        if (-not $u) { continue }
        $s = [string]$u.RawStatus
        if ([string]::IsNullOrWhiteSpace($s)) { $s = [string]$u.Status }
        if ($s -match '(?i)^install') { $inflight = 'Installing'; break }
        if ($s -match '(?i)pending\s+install|^queued') { if (-not $inflight) { $inflight = 'Downloading' } }
        if ($s -match '(?i)^download') { if (-not $inflight) { $inflight = 'Downloading' } }
        if ($s -match '(?i)^retrying') { if (-not $inflight) { $inflight = 'Installing' } }
    }
    $phaseIsCompleted = ($phase -eq 'Completed')
    if ($phaseIsCompleted -and $inflight) {
        $script:FbSplashCompletedLatch = $false
        $script:FbSplashLastStatusUpdatedAt = $updatedAt
        return $inflight
    }
    if (-not $phaseIsCompleted) {
        $script:FbSplashCompletedLatch = $false
        $script:FbSplashLastStatusUpdatedAt = $updatedAt
        return $phase
    }
    $script:FbSplashCompletedLatch = $true
    $script:FbSplashLastStatusUpdatedAt = $updatedAt
    return $phase
}

function Set-FbSplashHandoffLayout {
    param(
        [string]$StatusText = 'Preparing hardware checks',
        [string]$Header = 'Preparing hardware checks',
        [string]$Detail = 'Updates are complete. FirstBase will verify Wi-Fi, camera, and sound, then open YouTube or Settings.'
    )
    $script:FbSplashHandoffLayoutActive = $true
    try { Set-FbSplashPassStatus -Text $StatusText } catch {}
    if ($updatesList) {
        try { $updatesList.Visibility = [System.Windows.Visibility]::Collapsed } catch {}
    }
    if ($handoffCopyHost) {
        try { $handoffCopyHost.Visibility = [System.Windows.Visibility]::Visible } catch {}
    }
    if ($handoffEyebrowText) { try { $handoffEyebrowText.Text = 'OOBE HANDOFF' } catch {} }
    if ($handoffHeaderText) { try { $handoffHeaderText.Text = (Convert-FbSplashTextToAscii -Text $Header) } catch {} }
    if ($handoffDetailText) { try { $handoffDetailText.Text = (Convert-FbSplashTextToAscii -Text $Detail) } catch {} }
    if ($null -ne $warningText) {
        try { $warningText.Text = 'Do not disconnect power. Hardware checks run in this session.' } catch {}
    }
}

function Start-FbHandoffSplashProcess {
    param(
        [ValidateSet('preparing-handoff', 'restart-for-checks', 'running-checks', 'checks-pass', 'checks-fail', 'sealing', 'gate-fail-restart')]
        [string]$Phase = 'preparing-handoff'
    )
    $ps1 = Join-Path $PSScriptRoot 'FirstBaseHandoffSplash.ps1'
    if (-not (Test-Path -LiteralPath $ps1)) {
        $ps1 = 'C:\Windows\Setup\FirstBase\FirstBaseHandoffSplash.ps1'
    }
    if (-not (Test-Path -LiteralPath $ps1)) { return $false }
    try {
        $args = @(
            '-NoProfile', '-ExecutionPolicy', 'Bypass', '-STA',
            '-File', $ps1, '-Phase', $Phase, '-AutoCloseSeconds', '90'
        )
        Start-Process -FilePath 'powershell.exe' -ArgumentList $args -WindowStyle Normal -ErrorAction Stop | Out-Null
        Write-SplashLog ("Handoff splash started (phase={0})." -f $Phase) 'INFO'
        return $true
    } catch {
        try { Write-SplashLog ("Handoff splash start failed: {0}" -f $_.Exception.Message) 'WARN' } catch {}
        return $false
    }
}

function Get-FbSplashStateVersionText {
    # 2266: Populate ActivityText with pipeline state + script version so the status
    # area below the header is never blank.  Does NOT expose KB IDs or update titles.
    param([string]$PhaseOrPass)
    try {
        $phase = if ([string]::IsNullOrWhiteSpace($PhaseOrPass)) { 'Preparing' } else { $PhaseOrPass.Trim() }
        if ($script:FbSplashActivityPhase -ne $phase) {
            $script:FbSplashActivityPhase = $phase
            $script:FbSplashActivityPhaseStarted = Get-Date
        }

        $phaseLabel = switch -Regex ($phase) {
            '^Network$'   { 'Waiting for network'; break }
            '^Completed$' { 'Completed'; break }
            '^ApplyingUpdates$' { 'Applying updates'; break }
            '^ManualRestart$' { 'Restart required'; break }
            '^Reboot'     { 'Preparing to restart'; break }
            '^\d+$'       { "Update pass $phase"; break }
            '^Pass\s*(\d+)$' { "Update pass $($Matches[1])"; break }
            '^Preparing$' { 'Preparing your computer'; break }
            default       { ($phase -replace '([a-z])([A-Z])', '$1 $2') }
        }
        if ([string]::IsNullOrWhiteSpace($phaseLabel)) { $phaseLabel = 'Preparing your computer' }

        $elapsed = [TimeSpan]::Zero
        if ($script:FbSplashActivityPhaseStarted) {
            $elapsed = (Get-Date) - $script:FbSplashActivityPhaseStarted
        }
        $parts = New-Object System.Collections.Generic.List[string]
        [void]$parts.Add($phaseLabel)
        [void]$parts.Add(('Phase elapsed {0:hh\:mm\:ss}' -f $elapsed))

        $statePath = Join-Path $FbRoot 'wu-state.json'
        if (Test-Path -LiteralPath $statePath) {
            try {
                $diskState = Get-Content -LiteralPath $statePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                $reboots = 0
                $fromRi = 0
                $fromBoot = 0
                if ($diskState.PSObject.Properties.Name -contains 'RebootIterations') {
                    try { $fromRi = [math]::Max(0, [int]$diskState.RebootIterations) } catch { $fromRi = 0 }
                }
                if ($diskState.PSObject.Properties.Name -contains 'BootCount') {
                    try {
                        $bc = [int]$diskState.BootCount
                        if ($bc -gt 1) { $fromBoot = $bc - 1 }
                    } catch { $fromBoot = 0 }
                }
                $reboots = if ($fromRi -gt 0) { $fromRi } else { $fromBoot }
                if ($reboots -gt 0) { [void]$parts.Add(("Restarts $reboots")) }
                elseif ($diskState.PSObject.Properties.Name -contains 'BootCount' -and [int]$diskState.BootCount -gt 0) {
                    [void]$parts.Add(('Boot {0}' -f [int]$diskState.BootCount))
                }
            } catch {}
        }

        $versionBits = New-Object System.Collections.Generic.List[string]
        if (-not [string]::IsNullOrWhiteSpace([string]$script:ThisScriptVersion)) {
            [void]$versionBits.Add(('UI {0}' -f $script:ThisScriptVersion))
        }
        if (-not [string]::IsNullOrWhiteSpace([string]$FirstBasePayloadRevision) -and $FirstBasePayloadRevision -ne 'unknown') {
            [void]$versionBits.Add(('payload {0}' -f $FirstBasePayloadRevision))
        } elseif (-not [string]::IsNullOrWhiteSpace([string]$FirstBaseProductVersion)) {
            [void]$versionBits.Add(('FirstBase {0}' -f $FirstBaseProductVersion))
        }
        if ($versionBits.Count -gt 0) { [void]$parts.Add([string]::Join(' / ', $versionBits.ToArray())) }

        $line = [string]::Join('  |  ', $parts.ToArray())
        if (-not [string]::IsNullOrWhiteSpace($line)) { return $line }
    } catch {}
    return 'Preparing your computer'
}

function Remove-FbSplashPercentFromDisplayText {
    param([string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text)) { return '' }
    $t = [string]$Text
    $t = $t -replace '(?i)\s*\[\s*overall\s+\d+%\s*\]', ''
    $t = $t -replace '\(\d+%\)', ''
    $t = $t -replace '\b\d+%\b', ''
    return (($t -replace '\s{2,}', ' ').Trim())
}

function Limit-FbSplashUserMessage {
    param([string]$Text, [int]$MaxLen = 100)
    if ([string]::IsNullOrWhiteSpace($Text)) { return '' }
    $t = (Remove-FbSplashPercentFromDisplayText -Text $Text)
    if ($t.Length -le $MaxLen) { return $t }
    return ($t.Substring(0, $MaxLen).TrimEnd() + '...')
}

function Get-FbSplashSafeActivityMessage {
    param([string]$Text)
    $t = Limit-FbSplashUserMessage -Text $Text -MaxLen 180
    $t = Convert-FbSplashTextToAscii -Text $t
    if ([string]::IsNullOrWhiteSpace($t)) { return '' }
    # The loop's per-update callback includes the update title after the colon.
    # Preserve useful ordinal/transfer progress without exposing titles or KB IDs.
    if ($t -match '^(Downloading|Installing)\s+(\d+)\s+of\s+(\d+):') {
        $safe = ('{0} update {1} of {2}' -f $Matches[1], $Matches[2], $Matches[3])
        if ($t -match '-\s*(\d+MB\s*/\s*\d+MB)\s*$') { $safe += (' - {0}' -f $Matches[1]) }
        return $safe
    }
    $t = $t -replace '(?i)\bKB\d{4,}\b', 'an update'
    return (($t -replace '\s{2,}', ' ').Trim())
}

function Get-StatusVisual {
    param([string]$Status)

    $normalized = if ([string]::IsNullOrWhiteSpace($Status)) { 'Pending install' } else { (Remove-FbSplashPercentFromDisplayText -Text $Status.Trim()) }
    if ([string]::IsNullOrWhiteSpace($normalized)) { $normalized = 'Pending install' }
    $key = $normalized.ToLowerInvariant()

    # Honest end-states and in-flight states. Do not collapse reboot/retry
    # rows into Done - operators need to see when work is still owed.
    if ($key -match 'pending\s+restart|pending\s+reboot|^restart$') {
        return [pscustomobject]@{ Icon = '[!]'; Color = '#FFB388FF'; Status = 'Pending Restart'; IsActive = $false }
    }
    if ($key -match 'retry\s+next\s+boot') {
        return [pscustomobject]@{ Icon = '[R]'; Color = '#FFFF8A65'; Status = 'Retry Next Boot'; IsActive = $false }
    }
    if ($key -eq 'pending install' -or $key -eq 'queued') {
        return [pscustomobject]@{ Icon = '[ ]'; Color = '#FF9E9E9E'; Status = 'Queued'; IsActive = $false }
    }
    if ($key -eq 'downloading') {
        return [pscustomobject]@{ Icon = '[D]'; Color = '#FF4FC3F7'; Status = 'Downloading'; IsActive = $true }
    }
    if ($key -eq 'installing') {
        return [pscustomobject]@{ Icon = '[I]'; Color = '#FFFFB74D'; Status = 'Installing'; IsActive = $true }
    }
    if ($key -eq 'retrying') {
        return [pscustomobject]@{ Icon = '[R]'; Color = '#FFFF8A65'; Status = 'Retrying'; IsActive = $true }
    }
    if ($key -eq 'completed' -or $key -eq 'done') {
        return [pscustomobject]@{ Icon = '[*]'; Color = '#FF66BB6A'; Status = 'Done'; IsActive = $false }
    }
    if ($key -eq 'failed') {
        return [pscustomobject]@{ Icon = '[X]'; Color = '#FFEF5350'; Status = 'Failed'; IsActive = $false }
    }
    if ($key -match 'skipped|terminal') {
        return [pscustomobject]@{ Icon = '[X]'; Color = '#FF9E9E9E'; Status = 'Skipped'; IsActive = $false }
    }
    return [pscustomobject]@{ Icon = '[?]'; Color = '#FF90CAF9'; Status = $normalized; IsActive = $false }
}

function Get-LatestLog {
    if (-not (Test-Path $LogDir)) { return $null }
    Get-ChildItem -Path $LogDir -Filter 'WU-*.log' -ErrorAction SilentlyContinue |
        Sort-Object LastWriteTime -Descending |
        Select-Object -First 1
}

function Get-StatusFromStateFile {
    if (-not (Test-Path $StatusFile)) { return $null }
    $raw = $null
    $fs = $null
    $sr = $null
    try {
        $fs = [System.IO.File]::Open($StatusFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        $sr = New-Object System.IO.StreamReader($fs)
        $raw = $sr.ReadToEnd()
    } catch {
        try { $raw = Get-Content -Path $StatusFile -Raw -ErrorAction Stop } catch { return $null }
    } finally {
        try { if ($sr) { $sr.Dispose() } } catch {}
        try { if ($fs) { $fs.Dispose() } } catch {}
    }
    if ([string]::IsNullOrWhiteSpace($raw)) { return $null }
    try {
        $obj = $raw | ConvertFrom-Json -ErrorAction Stop
        $updates = @()
        foreach ($u in @($obj.updates)) {
            if (-not $u) { continue }
            $visual = Get-StatusVisual -Status ([string]$u.Status)
            $updates += [pscustomobject]@{
                Title   = (Convert-FbSplashTextToAscii -Text ([string]$u.Title))
                Status  = (Convert-FbSplashTextToAscii -Text ([string]$visual.Status))
                RawStatus = [string]$u.Status
                StatusIcon = [string]$visual.Icon
                StatusColor = [string]$visual.Color
                IsActive = [bool]$visual.IsActive
                Retries = [int]$u.Retries
            }
        }
        $updatedAt = ''
        try { $updatedAt = [string]$obj.updatedAt } catch { $updatedAt = '' }
        return [pscustomobject]@{
            Phase     = [string]$obj.phase
            Message   = [string]$obj.message
            UpdatedAt = $updatedAt
            Updates   = @($updates)
        }
    } catch {
        return $null
    }
}

function Invoke-FbSplashHydrateFromDisk {
    $state = Get-StatusFromStateFile
    if ($state -and @($state.Updates).Count -gt 0) {
        $displayPhase = Resolve-FbSplashDisplayPhase -State $state
        Set-FbSplashPassStatus -Text (Get-FbSplashShortStatusLine -PhaseOrPass $displayPhase) -Phase $displayPhase -Message ([string]$state.Message)
        Set-FbSplashUpdatesContent -Items $state.Updates
        return
    }
    if (@($script:FbSplashLastKnownUpdates).Count -gt 0) {
        Set-FbSplashUpdatesContent -Items $script:FbSplashLastKnownUpdates
        if ($state) {
            $displayPhase = Resolve-FbSplashDisplayPhase -State $state
            Set-FbSplashPassStatus -Text (Get-FbSplashShortStatusLine -PhaseOrPass $displayPhase) -Phase $displayPhase -Message ([string]$state.Message)
        }
        return
    }
    if ($state) {
        $displayPhase = Resolve-FbSplashDisplayPhase -State $state
        Set-FbSplashPassStatus -Text (Get-FbSplashShortStatusLine -PhaseOrPass $displayPhase) -Phase $displayPhase -Message ([string]$state.Message)
    }
}

function Set-FbSplashUpdatesContent {
    param([object[]]$Items)
    $list = @()
    if ($null -ne $Items) { $list = @($Items) }
    if ($list.Count -gt 0) {
        $script:FbSplashLastKnownUpdates = $list
    } elseif (-not $script:FbSplashHandoffLayoutActive -and @($script:FbSplashLastKnownUpdates).Count -gt 0) {
        $list = @($script:FbSplashLastKnownUpdates)
    }
    if ($script:FbSplashHandoffLayoutActive) {
        if ($updatesList) {
            try { $updatesList.Visibility = [System.Windows.Visibility]::Collapsed } catch {}
        }
        if ($handoffCopyHost) {
            try { $handoffCopyHost.Visibility = [System.Windows.Visibility]::Visible } catch {}
        }
        return
    }
    if ($updatesList) {
        $updatesList.ItemsSource = $list
        $updatesList.Visibility = [System.Windows.Visibility]::Visible
    }
    if ($updatesPlaceholder) {
        $updatesPlaceholder.Visibility = [System.Windows.Visibility]::Collapsed
    }
}

function Get-StatusFromLog {
    param($logFile)
    $result = [pscustomobject]@{ Pass = $null }
    if (-not $logFile -or -not (Test-Path $logFile.FullName)) { return $result }
    try {
        $tail = @()
        $fsLog = $null
        $srLog = $null
        try {
            $fsLog = [System.IO.File]::Open($logFile.FullName, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            $srLog = New-Object System.IO.StreamReader($fsLog)
            $allLog = $srLog.ReadToEnd()
            $arrLog = @($allLog -split "`r?`n")
            if ($arrLog.Count -gt 60) {
                $tail = @($arrLog[($arrLog.Count - 60)..($arrLog.Count - 1)])
            } else {
                $tail = $arrLog
            }
        } catch {
            $tail = @(Get-Content -Path $logFile.FullName -Tail 60 -ErrorAction SilentlyContinue)
        } finally {
            try { if ($srLog) { $srLog.Dispose() } } catch {}
            try { if ($fsLog) { $fsLog.Dispose() } } catch {}
        }
        # Most recent pass marker
        $passLine = $tail | Where-Object { $_ -match '=====\s*Pass:\s*(\S+)' } | Select-Object -Last 1
        if ($passLine -and $passLine -match '=====\s*Pass:\s*(\S+)') {
            $result.Pass = $Matches[1]
        }
        # Explicit network-wait status overrides pass label.
        $netWait = $tail | Where-Object { $_ -match 'No internet detected|Soft waiting|internet is unavailable' } | Select-Object -Last 1
        if ($netWait) {
            $result.Pass = 'Network'
            return $result
        }
    } catch {}
    return $result
}

function Start-FbSplashDeferredOobeSoundBootstrapIfPending {
    # 2234 (fb-dump-final-1121): when splash still launches on OOBE logon, spawn deferred Sound if armed.
    $pd = 'C:\ProgramData\FirstBase'
    $armSuppress = Join-Path $pd '.firstbase-specialize-arm-suppressed'
    $completed = Join-Path $pd '.pipeline-completed'
    $deliveryStarted = Join-Path $pd '.oobe-sound-delivery-started'
    $sealed = Join-Path $pd '.firstbase-sealed'
    $deferredMarker = Join-Path $pd '.deferred-oobe-sound-runonce-armed'
    $bootstrap = Join-Path $pd 'FirstBaseOobeDeferredSoundBootstrap.ps1'
    $deferred = Join-Path $pd 'FirstBaseDeferredOobeSound.ps1'
    if (-not (Test-Path -LiteralPath $armSuppress)) { return }
    if (Test-Path -LiteralPath $deliveryStarted) { return }
    if (Test-Path -LiteralPath $sealed) { return }
    if (Test-Path -LiteralPath $completed) { return }
    if (-not (Test-Path -LiteralPath $deferredMarker)) { return }
    $target = if (Test-Path -LiteralPath $bootstrap) { $bootstrap } elseif (Test-Path -LiteralPath $deferred) { $deferred } else { $null }
    if (-not $target) { return }
    try {
        Write-SplashLog ("2234: OOBE splash bootstrap spawning deferred Sound: {0}" -f $target) 'INFO'
        Start-Process -FilePath 'powershell.exe' -ArgumentList @(
            '-NoProfile', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Normal', '-File', $target
        ) -WindowStyle Normal -ErrorAction Stop
    } catch {
        try { Write-SplashLog ("2234: splash bootstrap spawn failed: {0}" -f $_.Exception.Message) 'WARN' } catch {}
    }
}

function Invoke-FbSplashMaybeStartOobeSoundAfterUpdates {
    # 2218: log-only when overlay mode is present  -  does NOT open Sound or ms-settings here.
    # Deferred work: HKLM RunOnce OpenWindowsSoundSettingsDeferredOnce -> FirstBaseDeferredOobeSound.ps1
    # after firmware reboot (Invoke-SysprepToOobe + shutdown /r /fw). This function only records that the
    # splash closed without spawning Sound on the audit-mode boot (by design).
    if (-not (Test-Path -LiteralPath $FbSplashOobeOverlayMode)) { return }
    try {
        Write-SplashLog '2218 OOBE Sound: splash exit - deferred Sound path (no ms-settings on this boot).' 'INFO'
    } catch {}
}

function Invoke-FbSplash2224HandoffTopmostRefreshMaybe {
    try {
        if (-not (Test-FbSplash2222OobeOverlayHandoffActive)) { return }
        if ($script:UserPreferredTopmostOff) { return }
        $hwSplash = $script:SplashNativeHwnd
        if ($hwSplash -eq [IntPtr]::Zero) { return }
        $now = [DateTimeOffset]::UtcNow
        if ($null -ne $script:Splash2224HandoffTopmostLastUtc) {
            if (($now - $script:Splash2224HandoffTopmostLastUtc).TotalSeconds -lt 5) { return }
        }
        $script:Splash2224HandoffTopmostLastUtc = $now
        $yieldHandoff = $false
        try { $yieldHandoff = [bool](Invoke-FbSplashHonorOperatorForeground) } catch { $yieldHandoff = $false }
        if (-not $yieldHandoff) {
            $window.Topmost = $true
            Invoke-FbSplashApplyWin32ZOrder -WantTopmost $true
        }
        $script:Oobe2214mDid2214lPass1ZStompThisTick = $false
        Invoke-FbSplashOobe2214lPlaceWwahostRootBehindSplash -RestackPass 1
        if ($yieldHandoff) {
            try { Invoke-FbSplashHonorOperatorForeground | Out-Null } catch {}
        }
        Write-SplashLog '2224f: handoff main-timer extra Topmost + 2214l pass=1 (no WWAHost SW_MIN; 2214j unchanged)' 'INFO'
    } catch {
        try { Write-SplashLog ("2224f: handoff topmost refresh EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch { }
    }
}

function Invoke-FbSplashHonorOperatorSettingsGate {
    # Settings (and other operator windows) must paint above splash. Do not
    # minimize the splash - keep it fullscreen behind those apps, still above OOBE.
    $active = $false
    try { $active = Test-Path -LiteralPath $FbSplashOperatorGateActive } catch { $active = $false }
    if ($active) {
        if ($script:FbSplashOperatorGateStoodDown) { return }
        $script:FbSplashOperatorGateStoodDown = $true
        try {
            try { Invoke-FbSplashHonorOperatorForeground | Out-Null } catch {}
            Write-SplashLog '2380: operator Settings gate active - splash stays fullscreen; Settings/cmd raised above splash (OOBE remains behind).' 'INFO'
        } catch {
            try { Write-SplashLog ("2380: operator Settings gate stand-down EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch {}
        }
    } else {
        if ($script:FbSplashOperatorGateStoodDown) {
            $script:FbSplashOperatorGateStoodDown = $false
            try { Write-SplashLog '2380: operator Settings gate marker cleared - splash remains visible through scrub/seal.' 'INFO' } catch {}
        }
    }
}

try {
    Write-SplashLog "Configuring main DispatcherTimer (interval=1s)..."
} catch {}
$timer = New-Object System.Windows.Threading.DispatcherTimer
$script:timer = $timer
$timer.Interval = [TimeSpan]::FromSeconds(1)
$timer.Add_Tick({
    try { Invoke-FbSplashHonorOperatorSettingsGate } catch {}
    # 2305: seal-window teardown - the update loop opened the OOBE handoff seal window; stand down so only the real
    # customer OOBE shows (the splash can no longer take the foreground once Layer 2 is seal-gated). Bypasses the
    # Updates-Done close guard via $script:FbSplashTeardownRequested.
    if (Test-Path -LiteralPath $FbSplashSealTeardownMarker) {
        try { Write-SplashLog '2305: seal-window teardown marker present; closing splash so the customer OOBE is clean.' 'INFO' } catch {}
        $script:FbSplashTeardownRequested = $true
        try { if ($null -ne $script:SplashTopmostRefreshTimer) { $script:SplashTopmostRefreshTimer.Stop() } } catch {}
        try { $script:timer.Stop() } catch {}
        try { $window.Close() } catch {}
        return
    }
    if (Test-Path $Marker) {
        # 2221: OOBE overlay handoff - keep splash visible with alternate copy until overlay marker drops
        # (scrub removes it). Follow-up: optional max-wait timeout if fleet ever sees a stuck marker.
        # 2256: Operator-done markers override stale overlay.mode (finalize must remove overlay; guard anyway).
        $fbOperatorDoneForUi = $false
        try {
            $fbOperatorDoneForUi =
                (Test-Path -LiteralPath $FbSplashPipelineCompletedMarker) -or
                (Test-Path -LiteralPath $FbSealedMarker)
        } catch {}
        if (-not $fbOperatorDoneForUi -and (Test-Path -LiteralPath $FbSplashOobeOverlayMode)) {
            if (-not $script:Splash2218DeferCloseForOobeOverlay) {
                $script:Splash2218DeferCloseForOobeOverlay = $true
                try {
                    Set-FbSplashHandoffLayout
                    Write-SplashLog '2221: marker + FirstBase-Splash-Oobe-Overlay.mode - handoff layout (KB list hidden); launching dedicated handoff splash.' 'INFO'
                } catch {
                    try { Write-SplashLog ("2221: handoff UI setup EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch { }
                }
            }
            if (-not $script:FbSplashHandoffHostStarted) {
                $script:FbSplashHandoffHostStarted = $true
                $handoffStarted = $false
                try { $handoffStarted = [bool](Start-FbHandoffSplashProcess -Phase 'preparing-handoff') } catch { $handoffStarted = $false }
                if ($handoffStarted) {
                    $script:FbSplashClosingForHandoffSwitch = $true
                    try { if ($null -ne $script:SplashTopmostRefreshTimer) { $script:SplashTopmostRefreshTimer.Stop() } } catch {}
                    try { $script:timer.Stop() } catch {}
                    try { $window.Close() } catch {}
                    return
                }
                try { Write-SplashLog 'Handoff splash host failed to start; keeping updates splash in handoff layout (no KB list).' 'WARN' } catch {}
            }
            Invoke-FbSplash2224HandoffTopmostRefreshMaybe
            Set-FbSplashElapsedDisplay -Elapsed ((Get-Date) - $script:startTime)
            Update-FbSplashTotalElapsed -Freeze
            Set-FbSplashRebootDisplay
            return
        }
        try { Invoke-FbSplashMaybeStartOobeSoundAfterUpdates } catch {}
        try { Invoke-FbSplashOobe2214cRestoreAll -Reason 'marker-main-timer' } catch {}
        try { if ($null -ne $script:SplashTopmostRefreshTimer) { $script:SplashTopmostRefreshTimer.Stop() } } catch {}
        $script:timer.Stop()
        $window.Close()
        return
    }

    $state = Get-StatusFromStateFile
    $status = $null
    if ($state) {
        $displayPhase = Resolve-FbSplashDisplayPhase -State $state
        Set-FbSplashPassStatus -Text (Get-FbSplashShortStatusLine -PhaseOrPass $displayPhase) -Phase $displayPhase -Message ([string]$state.Message)
        if (@($state.Updates).Count -gt 0) {
            Set-FbSplashUpdatesContent -Items $state.Updates
        } else {
            Set-FbSplashUpdatesContent -Items @($script:FbSplashLastKnownUpdates)
        }
    } else {
        $log = Get-LatestLog
        $status = Get-StatusFromLog $log
        $fallbackPhase = $status.Pass
        if ([string]::IsNullOrWhiteSpace($fallbackPhase) -and @($script:FbSplashLastKnownUpdates).Count -gt 0) {
            $fallbackPhase = 'Rebooting'
        }
        Set-FbSplashPassStatus -Text (Get-FbSplashShortStatusLine -PhaseOrPass $fallbackPhase) -Phase $fallbackPhase
        Set-FbSplashUpdatesContent -Items @($script:FbSplashLastKnownUpdates)
    }

    Set-FbSplashElapsedDisplay -Elapsed ((Get-Date) - $script:startTime)
    Update-FbSplashTotalElapsed
    Set-FbSplashRebootDisplay
    try { Invoke-FbSplashHonorOperatorForeground | Out-Null } catch {}
})
if (-not $script:Preview) {
    try {
        Invoke-FbSplashHydrateFromDisk
    } catch {}
    try {
        $timer.Start()
        Write-SplashLog "Main DispatcherTimer started"
    } catch {
        Write-SplashLog "FAILED to start main DispatcherTimer: $($_.Exception.GetType().FullName): $($_.Exception.Message)" 'ERROR'
        throw
    }
}

# Block Alt-F4 / window close so a curious user can't dismiss it
$window.Add_Closing({
    if ($script:Preview) { return }
    # 2305: allow the close when a seal-window teardown was requested even though Updates-Done.flag is absent
    # (normal path still requires the flag so a curious user cannot dismiss the splash mid-update).
    if (-not (Test-Path $Marker) -and -not $script:FbSplashTeardownRequested) {
        $_.Cancel = $true
        return
    }
    if ($script:FbSplashClosingForHandoffSwitch) {
        try { if ($null -ne $script:SplashTopmostRefreshTimer) { $script:SplashTopmostRefreshTimer.Stop() } } catch {}
        return
    }
    try { Invoke-FbSplashMaybeStartOobeSoundAfterUpdates } catch {}
    try { Invoke-FbSplashOobe2214cRestoreAll -Reason 'splash-closing' } catch {}
    try { if ($null -ne $script:SplashTopmostRefreshTimer) { $script:SplashTopmostRefreshTimer.Stop() } } catch {}
})

# 2213u + 2213z + 2214a: WPF Topmost can drop after Maximize; OOBE needs Win32 HWND_TOPMOST + WS_EX_TOPMOST re-apply.
$window.Add_Loaded({
    if (-not $script:Preview) {
        try {
            try { Invoke-FbSplashCoverScreen -Window $window } catch {}
            $yieldLoaded = $false
            try { $yieldLoaded = [bool](Invoke-FbSplashHonorOperatorForeground) } catch { $yieldLoaded = $false }
            if (-not $script:UserPreferredTopmostOff -and -not $yieldLoaded) {
                $window.Topmost = $true
                Invoke-FbSplashApplyWin32ZOrder -WantTopmost $true
            }
            if (-not $yieldLoaded) {
                [void]$window.Activate()
                Invoke-FbSplashTryForegroundOnce
            }
            Invoke-FbSplash2228OverlayEarlyZOrderPass -Reason 'Loaded'
            Start-FbSplashDeferredOobeSoundBootstrapIfPending
            # 2241: confirm splash is actually on screen (Loaded + Win32 IsWindowVisible).
            try {
                $hw2241 = $script:SplashNativeHwnd
                if ($hw2241 -ne [IntPtr]::Zero -and [FbSplashWin32Z]::IsWindowVisible($hw2241)) {
                    $script:FbSplashConfirmedVisible = $true
                    Write-SplashLog ("2241: splash-confirmed-visible set=True (Loaded + IsWindowVisible hwnd={0})" -f $hw2241)
                }
            } catch {}
            try {
                Invoke-FbSplashOobe2214eMinimizeForegroundOobeRoot
                Invoke-FbSplashOobe2214cApplyMinimizeWhileUpdates
            } catch {}
            # 2308: ActualSize is reliable after Loaded (SourceInitialized often still reports 0x0).
            try {
                $vb = $window.FindName('RootScaleBox')
                $dc = $window.FindName('DesignCanvas')
                $scaleX = if ($dc -and $dc.Width -gt 0 -and $window.ActualWidth -gt 0) { [math]::Min(1.0, $window.ActualWidth / $dc.Width) } else { 1.0 }
                $scaleY = if ($dc -and $dc.Height -gt 0 -and $window.ActualHeight -gt 0) { [math]::Min(1.0, $window.ActualHeight / $dc.Height) } else { 1.0 }
                $fit = [math]::Min($scaleX, $scaleY)
                Write-SplashLog ("2308 fit Loaded: window={0:N0}x{1:N0} design=1280x800 uniformScale={2:N3} screen={3:N0}x{4:N0}" -f $window.ActualWidth, $window.ActualHeight, $fit, [System.Windows.SystemParameters]::PrimaryScreenWidth, [System.Windows.SystemParameters]::PrimaryScreenHeight)
            } catch {}
        } catch {}
        try {
            if ($null -ne $script:SplashTopmostRefreshTimer) {
                $script:SplashTopmostRefreshTimer.Start()
            }
        } catch {}
    }
})

# 2026.05.13.2213c + 2213u + 2221 key handling:
# F12 toggles Topmost (with a 2s on-screen indicator); default Topmost is
# ON (2213u/2213z/2214a) for OOBE-path visibility - F12 still lets a tech turn it off.
# Esc closes radial / embedded fb-im. Splash stays fullscreen (not minimizeable).
# Window is borderless maximized (2221) for OOBE dominance; Win32 topmost stack
# still applies on Loaded + periodic tick, but operator apps (Settings, cmd)
# are raised above splash so they stay usable. Other keys are not swallowed.
$window.Add_KeyDown({
    param($s, $e)
    try {
        if ($e.Key -eq [System.Windows.Input.Key]::F12) {
            $newTopmost = -not $window.Topmost
            $window.Topmost = $newTopmost
            $script:UserPreferredTopmostOff = -not $newTopmost
            Invoke-FbSplashApplyWin32ZOrder -WantTopmost $newTopmost
            if ($script:UserPreferredTopmostOff) {
                try { Invoke-FbSplashOobe2214cRestoreAll -Reason 'f12-topmost-off' } catch {}
            }
            if ($script:TopmostIndicatorText) {
                $script:TopmostIndicatorText.Text = if ($newTopmost) { 'Always-on-top: ON' } else { 'Always-on-top: OFF' }
            }
            if ($script:TopmostIndicator) {
                $script:TopmostIndicator.Visibility = [System.Windows.Visibility]::Visible
            }
            try { $script:TopmostIndicatorTimer.Stop() } catch {}
            try { $script:TopmostIndicatorTimer.Start() } catch {}
            $e.Handled = $true
        }
        elseif ($e.Key -eq [System.Windows.Input.Key]::Escape) {
            if ($script:Preview) {
                $window.Close()
            } else {
                try {
                    if ($script:FbSplashFbImOpen) { Hide-FbSplashFbImHost; $e.Handled = $true; return }
                    if ($script:FbSplashRadialOpen) { Hide-FbSplashRadialMenu; $e.Handled = $true; return }
                } catch {}
            }
            $e.Handled = $true
        }
    } catch {}
})

if ($script:Preview) {
    $window.WindowStyle = [System.Windows.WindowStyle]::SingleBorderWindow
    $window.WindowState = [System.Windows.WindowState]::Normal
    $window.Topmost = $false
    $window.ResizeMode = [System.Windows.ResizeMode]::CanResize
    $window.Width = 1180; $window.Height = 940
    $window.Title = ('FirstBase Updates - PREVIEW ({0})' -f $script:PreviewScenario)
    Set-FbSplashPassStatus -Text 'Downloading and installing updates'

    $sampleStatic = @(
        [pscustomobject]@{ Title='2025-06 Cumulative Update for Windows 11 (KB5039212)'; StatusColor='#FF66BB6A'; Status='Done';             Retries=0 }
        [pscustomobject]@{ Title='Security Intelligence Update for Microsoft Defender'; StatusColor='#FFFFB74D'; Status='Installing';       Retries=0 }
        [pscustomobject]@{ Title='.NET 8.0.x Update for x64 Client';                    StatusColor='#FFB388FF'; Status='Pending Restart'; Retries=0 }
        [pscustomobject]@{ Title='Windows Malicious Software Removal Tool x64';         StatusColor='#FFFF8A65'; Status='Retry Next Boot'; Retries=1 }
        [pscustomobject]@{ Title='Intel - System - Chipset Driver Update';             StatusColor='#FFFF8A65'; Status='Retrying';         Retries=1 }
        [pscustomobject]@{ Title='Servicing Stack Update for Windows 11 (KB5039338)';  StatusColor='#FF4FC3F7'; Status='Downloading';     Retries=0 }
        [pscustomobject]@{ Title='Microsoft Edge Stable Channel Update';              StatusColor='#FF9E9E9E'; Status='Queued';          Retries=0 }
        [pscustomobject]@{ Title='Windows Recovery Environment Update';               StatusColor='#FF9E9E9E'; Status='Queued';          Retries=0 }
        [pscustomobject]@{ Title='NVIDIA Graphics Driver Update';                     StatusColor='#FF9E9E9E'; Status='Queued';          Retries=0 }
        [pscustomobject]@{ Title='Realtek Audio Driver Update';                       StatusColor='#FF9E9E9E'; Status='Queued';          Retries=0 }
        [pscustomobject]@{ Title='Intel Management Engine Interface Driver';          StatusColor='#FF9E9E9E'; Status='Queued';          Retries=0 }
        [pscustomobject]@{ Title='Definition Update for Windows Defender Antivirus';  StatusColor='#FF66BB6A'; Status='Done';            Retries=0 }
        [pscustomobject]@{ Title='HP Inc. - Firmware - System Firmware Update';      StatusColor='#FF9E9E9E'; Status='Queued';          Retries=0 }
        [pscustomobject]@{ Title='Microsoft .NET Framework 4.8.1 Update';            StatusColor='#FF9E9E9E'; Status='Queued';          Retries=0 }
        [pscustomobject]@{ Title='Windows 11 Setup Updates (KB5043080)';             StatusColor='#FF9E9E9E'; Status='Queued';          Retries=0 }
        [pscustomobject]@{ Title='Dell Inc. - Firmware - BIOS Update';               StatusColor='#FF9E9E9E'; Status='Queued';          Retries=0 }
    )

    if ($script:PreviewScenario -eq 'Checking') {
        Set-FbSplashPassStatus -Text 'Checking for updates'
        Set-FbSplashUpdatesContent -Items @()
        Set-FbSplashElapsedDisplay -Elapsed ([TimeSpan]::FromSeconds(12))
        Set-FbSplashTotalElapsedDisplay -Elapsed ([TimeSpan]::FromSeconds(12))
        Set-FbSplashRebootDisplay -Count 0
    }
    elseif ($script:PreviewScenario -eq 'Pulling') {
        # Animated pipeline: empty check -> queued -> download/install progress -> done.
        # Frames advance on a DispatcherTimer so the operator sees the real UI transitions.
        $script:FbPreviewPullFrame = 0
        $script:FbPreviewPullStarted = Get-Date
        # Fake an earlier pipeline start so TOTAL ELAPSED > session ELAPSED.
        $script:FbPreviewPipelineStarted = (Get-Date).AddMinutes(-47)
        $script:FbPreviewPullTitles = @(
            '2025-06 Cumulative Update for Windows 11 (KB5039212)'
            'Security Intelligence Update for Microsoft Defender'
            '.NET 8.0.x Update for x64 Client'
            'Windows Malicious Software Removal Tool x64'
        )
        $script:FbPreviewPullAdvance = {
            try {
                $i = [int]$script:FbPreviewPullFrame
                Set-FbSplashElapsedDisplay -Elapsed ((Get-Date) - $script:FbPreviewPullStarted)
                Set-FbSplashTotalElapsedDisplay -Elapsed ((Get-Date) - $script:FbPreviewPipelineStarted)
                # Demo reboot count rising across the pull sequence.
                $rebootDemo = if ($i -le 1) { 0 } elseif ($i -le 3) { 1 } else { 2 }
                Set-FbSplashRebootDisplay -Count $rebootDemo
                $t = $script:FbPreviewPullTitles

                switch ($i) {
                    0 {
                        Set-FbSplashPassStatus -Text 'Checking for updates'
                        Set-FbSplashUpdatesContent -Items @()
                    }
                    1 {
                        Set-FbSplashPassStatus -Text 'Updates found - preparing download'
                        Set-FbSplashUpdatesContent -Items @(
                            [pscustomobject]@{ Title=$t[0]; StatusIcon='[ ]'; StatusColor='#FF9E9E9E'; Status='Queued'; IsActive=$false; Retries=0 }
                            [pscustomobject]@{ Title=$t[1]; StatusIcon='[ ]'; StatusColor='#FF9E9E9E'; Status='Queued'; IsActive=$false; Retries=0 }
                            [pscustomobject]@{ Title=$t[2]; StatusIcon='[ ]'; StatusColor='#FF9E9E9E'; Status='Queued'; IsActive=$false; Retries=0 }
                            [pscustomobject]@{ Title=$t[3]; StatusIcon='[ ]'; StatusColor='#FF9E9E9E'; Status='Queued'; IsActive=$false; Retries=0 }
                        )
                    }
                    2 {
                        Set-FbSplashPassStatus -Text 'Downloading and installing updates'
                        Set-FbSplashUpdatesContent -Items @(
                            [pscustomobject]@{ Title=$t[0]; StatusIcon='[D]'; StatusColor='#FF4FC3F7'; Status='Downloading'; IsActive=$true;  Retries=0 }
                            [pscustomobject]@{ Title=$t[1]; StatusIcon='[ ]'; StatusColor='#FF9E9E9E'; Status='Queued';      IsActive=$false; Retries=0 }
                            [pscustomobject]@{ Title=$t[2]; StatusIcon='[ ]'; StatusColor='#FF9E9E9E'; Status='Queued';      IsActive=$false; Retries=0 }
                            [pscustomobject]@{ Title=$t[3]; StatusIcon='[ ]'; StatusColor='#FF9E9E9E'; Status='Queued';      IsActive=$false; Retries=0 }
                        )
                    }
                    3 {
                        Set-FbSplashPassStatus -Text 'Downloading and installing updates'
                        Set-FbSplashUpdatesContent -Items @(
                            [pscustomobject]@{ Title=$t[0]; StatusIcon='[*]'; StatusColor='#FF66BB6A'; Status='Done';        IsActive=$false; Retries=0 }
                            [pscustomobject]@{ Title=$t[1]; StatusIcon='[I]'; StatusColor='#FFFFB74D'; Status='Installing';  IsActive=$true;  Retries=0 }
                            [pscustomobject]@{ Title=$t[2]; StatusIcon='[D]'; StatusColor='#FF4FC3F7'; Status='Downloading'; IsActive=$true;  Retries=0 }
                            [pscustomobject]@{ Title=$t[3]; StatusIcon='[ ]'; StatusColor='#FF9E9E9E'; Status='Queued';      IsActive=$false; Retries=0 }
                        )
                    }
                    4 {
                        Set-FbSplashPassStatus -Text 'Finishing updates'
                        Set-FbSplashUpdatesContent -Items @(
                            [pscustomobject]@{ Title=$t[0]; StatusIcon='[*]'; StatusColor='#FF66BB6A'; Status='Done';       IsActive=$false; Retries=0 }
                            [pscustomobject]@{ Title=$t[1]; StatusIcon='[*]'; StatusColor='#FF66BB6A'; Status='Done';       IsActive=$false; Retries=0 }
                            [pscustomobject]@{ Title=$t[2]; StatusIcon='[I]'; StatusColor='#FFFFB74D'; Status='Installing'; IsActive=$true;  Retries=0 }
                            [pscustomobject]@{ Title=$t[3]; StatusIcon='[R]'; StatusColor='#FFFF8A65'; Status='Retrying';   IsActive=$true;  Retries=1 }
                        )
                    }
                    default {
                        Set-FbSplashPassStatus -Text 'Updates complete'
                        Set-FbSplashUpdatesContent -Items @(
                            [pscustomobject]@{ Title=$t[0]; StatusIcon='[*]'; StatusColor='#FF66BB6A'; Status='Done'; IsActive=$false; Retries=0 }
                            [pscustomobject]@{ Title=$t[1]; StatusIcon='[*]'; StatusColor='#FF66BB6A'; Status='Done'; IsActive=$false; Retries=0 }
                            [pscustomobject]@{ Title=$t[2]; StatusIcon='[*]'; StatusColor='#FF66BB6A'; Status='Done'; IsActive=$false; Retries=0 }
                            [pscustomobject]@{ Title=$t[3]; StatusIcon='[*]'; StatusColor='#FF66BB6A'; Status='Done'; IsActive=$false; Retries=0 }
                        )
                    }
                }
                $script:FbPreviewPullFrame = $i + 1
            } catch {}
        }

        & $script:FbPreviewPullAdvance
        $previewPullTimer = New-Object System.Windows.Threading.DispatcherTimer
        $previewPullTimer.Interval = [TimeSpan]::FromSeconds(1)
        $previewPullTimer.Add_Tick({
            try {
                if ([int]$script:FbPreviewPullFrame -gt 5) {
                    $previewPullTimer.Stop()
                    return
                }
                & $script:FbPreviewPullAdvance
            } catch {}
        })
        $previewPullTimer.Start()
        $window.Add_Closed({ try { $previewPullTimer.Stop() } catch {} })
    }
    else {
        # Static sample list (historical default preview).
        Set-FbSplashUpdatesContent -Items $sampleStatic
        Set-FbSplashElapsedDisplay -Elapsed ([TimeSpan]::FromSeconds(444))
        Set-FbSplashTotalElapsedDisplay -Elapsed ([TimeSpan]::FromSeconds(7320))
        Set-FbSplashRebootDisplay -Count 1
    }

    $previewTimer = New-Object System.Windows.Threading.DispatcherTimer
    $previewTimer.Interval = [TimeSpan]::FromSeconds( $(if ($script:PreviewScenario -eq 'Pulling') { 120 } else { 90 }) )
    $previewTimer.Add_Tick({ try { $previewTimer.Stop(); $window.Close() } catch {} })
    $previewTimer.Start()

    # 2300 Phase 0 test hook: with -SimulateOobeForeground, spawn a dummy topmost "OOBE" window and drive the
    # suppression tick (diagnostics + Layer 2 kill) on a preview-only timer, since the production refresh timer
    # does not start in -Preview. Lets the reclaim/kill logic be smoke-tested off-hardware.
    if ($script:SimulateOobeForeground) {
        try {
            Start-FbSplashSimulatedOobeForeground
            $script:FbSuppressionSimTimer = New-Object System.Windows.Threading.DispatcherTimer
            $script:FbSuppressionSimTimer.Interval = [TimeSpan]::FromSeconds(1.5)
            $script:FbSuppressionSimTimer.Add_Tick({ try { Invoke-FbSplashSuppressionDiagnosticsAndKillTick } catch {} })
            $script:FbSuppressionSimTimer.Start()
            $window.Add_Closed({
                try { if ($null -ne $script:FbSuppressionSimTimer) { $script:FbSuppressionSimTimer.Stop() } } catch {}
                try { if ($null -ne $script:FbSimulatedOobePid) { Stop-Process -Id ([int]$script:FbSimulatedOobePid) -Force -ErrorAction SilentlyContinue } } catch {}
                try { if ($script:FbSimulatedOobeScript -and (Test-Path -LiteralPath $script:FbSimulatedOobeScript)) { Remove-Item -LiteralPath $script:FbSimulatedOobeScript -Force -ErrorAction SilentlyContinue } } catch {}
            })
            Write-SplashSuppressionLog '2300 SimulateOobeForeground: preview suppression tick timer started (1.5s).'
        } catch {
            try { Write-SplashSuppressionLog ("2300 SimulateOobeForeground: preview setup EXCEPTION {0}" -f $_.Exception.Message) 'WARN' } catch {}
        }
    }
}

try {
    Write-SplashLog "About to call ShowDialog() - WPF dispatcher takes over here"
    try {
        try {
            $elapsedPulse = $window.TryFindResource('ElapsedPulse')
            if ($elapsedPulse -and $elapsedHost) {
                $elapsedPulse.Begin($window, $true)
            }
        } catch {
            try { Write-SplashLog ("Elapsed pulse start failed: {0}" -f $_.Exception.Message) 'WARN' } catch {}
        }
        if (-not $script:Preview) {
            Set-FbSplashElapsedDisplay -Elapsed ([TimeSpan]::Zero)
            Update-FbSplashTotalElapsed
        }
        $dialogResult = $window.ShowDialog()
        Write-SplashLog "ShowDialog() returned: $dialogResult (window closed normally)"
    } finally {
        try { Invoke-FbSplashOobe2214cRestoreAll -Reason 'showdialog-finally' } catch {}
    }
} catch {
    Write-SplashLog "ShowDialog() THREW: $($_.Exception.GetType().FullName): $($_.Exception.Message) | StackTrace: $($_.ScriptStackTrace)" 'ERROR'
    throw
}

Write-SplashLog "EXIT: Show-UpdateProgress.ps1 completing normally"
